/* ==========================================================================
   KONSEP 20 — KALEIDOSCOPE TYPE MANDALA (2027 • CHEERS • JOY)
   Theme: Happy New Year 2027 | Duration: 20s | Scenes: 4 | Aspect Ratio: 16:9
   Resolution: FHD / 2K / 4K (3840x2160) | Recommended Export Bitrate: 100 Mbps
   Style: Electric Turquoise + Vibrant Fuchsia on Deep Teal —
          12-Fold Radial Kaleidoscope Symmetry, Counter-Rotating Bands & Morph
   Pure Canvas 2D API — Zero Background Glow, Zero Overlaps, Seamless Loop
   ========================================================================== */

const EXPORT_CONFIG = {
  width: 3840,
  height: 2160,
  aspectRatio: '16:9',
  fps: 60,
  duration: 20,
  bitrateMbps: 100,
  minBitrateMbps: 100,
  videoBitsPerSecond: 100000000
};

const K20_PALETTE = {
  bgTop: '#03181C',
  bgMid: '#05272F',
  bgBot: '#031B20',
  coreBg: '#042027',
  turquoise: '#1CE8D0',
  turquoiseBright: '#7CF7E8',
  turquoiseDeep: '#0CA896',
  fuchsia: '#FF2E93',
  fuchsiaBright: '#FF86C4',
  fuchsiaDeep: '#C9126B',
  wireTurq: 'rgba(124, 247, 232, 0.26)',
  wireFuch: 'rgba(255, 134, 196, 0.22)',
  wireMuted: 'rgba(124, 247, 232, 0.14)',
  whiteSoft: 'rgba(232, 252, 250, 0.85)'
};

const K20_TAU = Math.PI * 2;
const K20_DEG = Math.PI / 180;

function k20Clamp01(v) {
  return v < 0 ? 0 : (v > 1 ? 1 : v);
}

function k20Lerp(a, b, t) {
  return a + (b - a) * t;
}

function k20SubRange(t, a, b) {
  return k20Clamp01((t - a) / (b - a));
}

function k20EaseOutCubic(t) {
  const u = 1 - k20Clamp01(t);
  return 1 - u * u * u;
}

function k20EaseInCubic(t) {
  const u = k20Clamp01(t);
  return u * u * u;
}

function k20EaseInOutCubic(t) {
  const u = k20Clamp01(t);
  return u < 0.5 ? 4 * u * u * u : 1 - Math.pow(-2 * u + 2, 3) / 2;
}

function k20BuildSuperEllipseRing(cx, cy, rx, ry, power, steps) {
  const pts = [];
  for (let i = 0; i < steps; i++) {
    const a = (i / steps) * K20_TAU;
    const ca = Math.cos(a);
    const sa = Math.sin(a);
    pts.push([
      cx + Math.sign(ca) * Math.pow(Math.abs(ca), 2 / power) * rx,
      cy + Math.sign(sa) * Math.pow(Math.abs(sa), 2 / power) * ry
    ]);
  }
  return pts;
}

function k20BuildArcBand(cx, cy, rOuterX, rOuterY, rInnerX, rInnerY, aStart, aEnd, steps) {
  const pts = [];
  for (let i = 0; i <= steps; i++) {
    const a = aStart + (aEnd - aStart) * (i / steps);
    pts.push([cx + Math.cos(a) * rOuterX, cy + Math.sin(a) * rOuterY]);
  }
  for (let i = steps; i >= 0; i--) {
    const a = aStart + (aEnd - aStart) * (i / steps);
    pts.push([cx + Math.cos(a) * rInnerX, cy + Math.sin(a) * rInnerY]);
  }
  return pts;
}

function k20SampleCubic(p0, c1, c2, p1, steps) {
  const pts = [];
  for (let i = 1; i <= steps; i++) {
    const t = i / steps;
    const mt = 1 - t;
    pts.push([
      mt * mt * mt * p0[0] + 3 * mt * mt * t * c1[0] + 3 * mt * t * t * c2[0] + t * t * t * p1[0],
      mt * mt * mt * p0[1] + 3 * mt * mt * t * c1[1] + 3 * mt * t * t * c2[1] + t * t * t * p1[1]
    ]);
  }
  return pts;
}

function k20DedupRing(pts) {
  const out = [];
  for (let i = 0; i < pts.length; i++) {
    const p = pts[i];
    if (out.length === 0) out.push(p);
    else if (Math.hypot(p[0] - out[out.length - 1][0], p[1] - out[out.length - 1][1]) > 1e-6) {
      out.push(p);
    }
  }
  if (out.length > 2 && Math.hypot(out[out.length - 1][0] - out[0][0], out[out.length - 1][1] - out[0][1]) <= 1e-6) {
    out.pop();
  }
  return out;
}

/* Crisp Vector Typography Glyphs for "2027", "CHEERS", "JOY" */
const K20_GLYPHS = (function () {
  const make = (w, rawRings) => ({ w, rings: rawRings.map(k20DedupRing) });

  const gC = make(0.62, [k20BuildArcBand(0.35, 0.50, 0.30, 0.50, 0.145, 0.34, 0.22 * Math.PI, 1.78 * Math.PI, 36)]);
  const gH = make(0.66, [[[0, 0], [0.185, 0], [0.185, 0.41], [0.475, 0.41], [0.475, 0], [0.66, 0], [0.66, 1], [0.475, 1], [0.475, 0.59], [0.185, 0.59], [0.185, 1], [0, 1]]]);
  const gE = make(0.58, [[[0, 0], [0.56, 0], [0.56, 0.175], [0.19, 0.175], [0.19, 0.415], [0.49, 0.415], [0.49, 0.585], [0.19, 0.585], [0.19, 0.825], [0.57, 0.825], [0.57, 1], [0, 1]]]);
  const gR = make(0.66, [
    [
      [0, 0], [0.37, 0],
      ...k20SampleCubic([0.37, 0], [0.55, 0], [0.63, 0.11], [0.63, 0.28], 14),
      ...k20SampleCubic([0.63, 0.28], [0.63, 0.43], [0.55, 0.535], [0.445, 0.555], 12),
      [0.66, 1.00], [0.45, 1.00], [0.265, 0.565], [0.19, 0.565], [0.19, 1.00], [0, 1.00]
    ],
    [
      [0.19, 0.165], [0.34, 0.165],
      ...k20SampleCubic([0.34, 0.165], [0.43, 0.165], [0.46, 0.20], [0.46, 0.28], 10),
      ...k20SampleCubic([0.46, 0.28], [0.46, 0.365], [0.43, 0.405], [0.34, 0.405], 10),
      [0.19, 0.405]
    ]
  ]);
  const gS = make(0.60, [[[0.05, 0.00], [0.55, 0.00], [0.55, 0.16], [0.22, 0.16], [0.22, 0.42], [0.56, 0.42], [0.56, 1.00], [0.05, 1.00], [0.05, 0.84], [0.39, 0.84], [0.39, 0.58], [0.05, 0.58]]]);
  const gJ = make(0.56, [[[0.36, 0.00], [0.54, 0.00], [0.54, 1.00], [0.06, 1.00], [0.06, 0.64], [0.22, 0.64], [0.22, 0.84], [0.36, 0.84]]]);
  const gO = make(0.66, [
    k20BuildSuperEllipseRing(0.33, 0.50, 0.31, 0.50, 2.5, 52),
    k20BuildSuperEllipseRing(0.33, 0.50, 0.15, 0.34, 2.4, 46)
  ]);
  const gY = make(0.66, [[[0, 0], [0.205, 0], [0.33, 0.36], [0.455, 0], [0.66, 0], [0.425, 0.56], [0.425, 1], [0.235, 1], [0.235, 0.56]]]);

  const d0 = gO;
  const d2 = make(0.66, [[
    [0.04, 0.31],
    ...k20SampleCubic([0.04, 0.31], [0.04, 0.09], [0.175, 0.00], [0.35, 0.00], 16),
    ...k20SampleCubic([0.35, 0.00], [0.535, 0.00], [0.64, 0.11], [0.64, 0.30], 16),
    ...k20SampleCubic([0.64, 0.30], [0.64, 0.51], [0.475, 0.65], [0.24, 0.84], 20),
    [0.64, 0.84], [0.64, 1.00], [0.02, 1.00], [0.02, 0.86],
    ...k20SampleCubic([0.02, 0.86], [0.21, 0.63], [0.465, 0.48], [0.465, 0.29], 20),
    ...k20SampleCubic([0.465, 0.29], [0.465, 0.18], [0.415, 0.15], [0.34, 0.15], 10),
    ...k20SampleCubic([0.34, 0.15], [0.25, 0.15], [0.205, 0.20], [0.205, 0.31], 10)
  ]]);
  const d7 = make(0.64, [[
    [0.02, 0.00], [0.62, 0.00], [0.62, 0.155],
    ...k20SampleCubic([0.62, 0.155], [0.485, 0.40], [0.38, 0.70], [0.34, 1.00], 20),
    [0.16, 1.00],
    ...k20SampleCubic([0.16, 1.00], [0.21, 0.70], [0.315, 0.40], [0.435, 0.155], 20),
    [0.145, 0.155], [0.145, 0.23], [0.02, 0.23]
  ]]);

  return { C: gC, H: gH, E: gE, R: gR, S: gS, J: gJ, O: gO, Y: gY, '0': d0, '2': d2, '7': d7 };
})();

/* Strict Non-Overlapping Concentric Radial Zones */
const K20_ZONES = {
  coreRimOuter: 0.122,
  coreRimInner: 0.114,
  band1MinR: 0.138,
  band1MaxR: 0.256,
  band2MinR: 0.274,
  band2MaxR: 0.422,
  outerBezelR: 0.433
};

function k20SectorRingPair(k) {
  /* Symmetry mapping around Sector 0 (12 o'clock):
     k=0 -> wave 0; pairs (1,11) -> 1; (2,10) -> 2; (3,9) -> 3; (4,8) -> 4; (5,7) -> 5; (6) -> 6 */
  return k === 0 ? 0 : (k <= 6 ? k : 12 - k);
}

function k20EvaluateState(loopT) {
  const duration = 20;
  const sceneCount = 4;
  const sceneDuration = duration / sceneCount;
  const safeScene = Math.max(0, Math.min(3, Math.floor(loopT / sceneDuration)));
  const p = (loopT % sceneDuration) / sceneDuration;

  let coreScale = 0;
  let coreAlpha = 0;
  let ringRotB = 0;
  let ringRotC = 0;
  let morph = 0;
  let arcSpanFrac = 0; /* Concentric ring closure [0..1] symmetrically from 12 o'clock */
  const sectorBScale = new Array(12).fill(0);
  const sectorBAlpha = new Array(12).fill(0);
  const sectorCScale = new Array(12).fill(0);
  const sectorCAlpha = new Array(12).fill(0);

  if (safeScene === 0) {
    /* Scene 0: Center "2027" enters cleanly, then 1 Single Master Sector (k = 0 at -90 deg) grows outward */
    const uCore = k20EaseOutCubic(k20SubRange(p, 0.04, 0.34));
    coreScale = uCore;
    coreAlpha = k20Clamp01(uCore / 0.28);

    const uB0 = k20EaseOutCubic(k20SubRange(p, 0.28, 0.66));
    const uC0 = k20EaseOutCubic(k20SubRange(p, 0.48, 0.90));
    sectorBScale[0] = uB0;
    sectorBAlpha[0] = k20Clamp01(uB0 / 0.25);
    sectorCScale[0] = uC0;
    sectorCAlpha[0] = k20Clamp01(uC0 / 0.25);
    arcSpanFrac = uB0 * (1 / 12);
  } else if (safeScene === 1) {
    /* Scene 1: Sector 0 stays locked -> mirrors symmetrically into all 12 sectors! */
    coreScale = 1;
    coreAlpha = 1;
    sectorBScale[0] = 1;
    sectorBAlpha[0] = 1;
    sectorCScale[0] = 1;
    sectorCAlpha[0] = 1;

    for (let k = 1; k < 12; k++) {
      const pairIdx = k20SectorRingPair(k); /* 1..6 */
      const start = 0.04 + (pairIdx - 1) * 0.115;
      const u = k20EaseOutCubic(k20SubRange(p, start, start + 0.26));
      sectorBScale[k] = u;
      sectorBAlpha[k] = k20Clamp01(u / 0.28);
      const uc = k20EaseOutCubic(k20SubRange(p, start + 0.05, start + 0.32));
      sectorCScale[k] = uc;
      sectorCAlpha[k] = k20Clamp01(uc / 0.28);
    }
    arcSpanFrac = (1 / 12) + (11 / 12) * k20EaseInOutCubic(k20SubRange(p, 0.04, 0.90));
  } else if (safeScene === 2) {
    /* Scene 2: Counter-Rotating Mandala Rings (+60 deg B / -60 deg C) + Geometric Morph + Pulsing "2027" */
    const spinEase = k20EaseInOutCubic(k20SubRange(p, 0.02, 0.96));
    ringRotB = spinEase * (60 * K20_DEG);   /* +2 * 30 deg exact symmetry step */
    ringRotC = -spinEase * (60 * K20_DEG);  /* -2 * 30 deg exact symmetry step */
    morph = 0.5 - 0.5 * Math.cos(p * K20_TAU * 2);
    coreScale = 1 + 0.095 * (0.5 - 0.5 * Math.cos(p * K20_TAU * 4));
    coreAlpha = 1;
    arcSpanFrac = 1;

    for (let k = 0; k < 12; k++) {
      sectorBScale[k] = 1;
      sectorBAlpha[k] = 1;
      sectorCScale[k] = 1;
      sectorCAlpha[k] = 1;
    }
  } else {
    /* Scene 3: Concentric Outside-In Collapse (Ring C -> Ring B -> Core "2027" -> Clean t = 0 Seam) */
    ringRotB = 60 * K20_DEG;
    ringRotC = -60 * K20_DEG;
    const uCOut = k20EaseInCubic(k20SubRange(p, 0.06, 0.44));
    const uBOut = k20EaseInCubic(k20SubRange(p, 0.34, 0.72));
    const uCoreOut = k20EaseInCubic(k20SubRange(p, 0.64, 0.94));

    const cSc = 1 - uCOut;
    const cAl = 1 - k20SubRange(p, 0.22, 0.44);
    const bSc = 1 - uBOut;
    const bAl = 1 - k20SubRange(p, 0.50, 0.72);
    coreScale = 1 - uCoreOut;
    coreAlpha = 1 - k20SubRange(p, 0.74, 0.94);
    arcSpanFrac = Math.max(0, 1 - k20EaseInOutCubic(k20SubRange(p, 0.25, 0.85)));

    for (let k = 0; k < 12; k++) {
      sectorCScale[k] = cSc;
      sectorCAlpha[k] = cAl;
      sectorBScale[k] = bSc;
      sectorBAlpha[k] = bAl;
    }
  }

  return {
    safeScene,
    p,
    coreScale,
    coreAlpha,
    ringRotB,
    ringRotC,
    morph,
    arcSpanFrac,
    sectorBScale,
    sectorBAlpha,
    sectorCScale,
    sectorCAlpha
  };
}

function k20MeasureWordWidth(word, h, gapRatio) {
  let w = 0;
  const gap = h * gapRatio;
  for (let i = 0; i < word.length; i++) {
    w += K20_GLYPHS[word[i]].w * h;
    if (i < word.length - 1) w += gap;
  }
  return w;
}

function k20DrawWordCentered(ctx, word, cx, cy, h, gapRatio, fillStyle) {
  const totalW = k20MeasureWordWidth(word, h, gapRatio);
  const gap = h * gapRatio;
  let curX = cx - totalW * 0.5;
  const y0 = cy - h * 0.5;
  ctx.fillStyle = fillStyle;

  for (let i = 0; i < word.length; i++) {
    const g = K20_GLYPHS[word[i]];
    ctx.beginPath();
    for (let r = 0; r < g.rings.length; r++) {
      const ring = g.rings[r];
      ctx.moveTo(curX + ring[0][0] * h, y0 + ring[0][1] * h);
      for (let m = 1; m < ring.length; m++) {
        ctx.lineTo(curX + ring[m][0] * h, y0 + ring[m][1] * h);
      }
      ctx.closePath();
    }
    ctx.fill('evenodd');
    curX += g.w * h + gap;
  }
}

function k20Polar(r, thetaDeg) {
  const rad = thetaDeg * K20_DEG;
  return [r * Math.cos(rad), r * Math.sin(rad)];
}

function k20FillSymmetricPolarPoly(ctx, polarPts, fillStyle) {
  /* Upper/positive-theta wing and mirrored negative-theta wing guaranteed strictly disjoint from text lane */
  for (let s = 0; s < 2; s++) {
    const sign = s === 0 ? 1 : -1;
    ctx.beginPath();
    for (let i = 0; i < polarPts.length; i++) {
      const [x, y] = k20Polar(polarPts[i][0], polarPts[i][1] * sign);
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.closePath();
    ctx.fillStyle = fillStyle;
    ctx.fill();
  }
}

/* Inner Kaleidoscope Band Sector (r in [0.138..0.256], |theta| <= 13 deg) */
function k20DrawInnerSector(ctx, k, scale, alpha, morph) {
  if (scale <= 0.005 || alpha <= 0.005) return;
  const angle = -Math.PI * 0.5 + k * (K20_TAU / 12);
  const rMid = (K20_ZONES.band1MinR + K20_ZONES.band1MaxR) * 0.5;
  const rDrawMid = k20Lerp(K20_ZONES.band1MinR + 0.005, rMid, scale);

  ctx.save();
  ctx.rotate(angle);
  ctx.globalAlpha *= alpha;
  ctx.translate(rDrawMid, 0);
  ctx.scale(scale, scale);
  ctx.translate(-rMid, 0);

  /* Bilaterally Symmetric Inner & Outer Crystal Blades flanking strictly outside text box */
  const bladeFlare = 7.5 + morph * 3.8;
  const innerBlade = [
    [0.141, 0.0],
    [0.150, bladeFlare * 0.65],
    [0.157, bladeFlare],
    [0.154, 0.0]
  ];
  ctx.beginPath();
  for (let i = 0; i < innerBlade.length; i++) {
    const [x, y] = k20Polar(innerBlade[i][0], innerBlade[i][1]);
    if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
  }
  for (let i = innerBlade.length - 1; i >= 0; i--) {
    const [x, y] = k20Polar(innerBlade[i][0], -innerBlade[i][1]);
    ctx.lineTo(x, y);
  }
  ctx.closePath();
  ctx.fillStyle = (k % 2 === 0) ? K20_PALETTE.turquoise : K20_PALETTE.fuchsiaBright;
  ctx.fill();

  const outerCrown = [
    [0.238, 0.0],
    [0.244, 6.0 + morph * 3.5],
    [0.254, 2.0 + morph * 2.5],
    [0.250, 0.0]
  ];
  ctx.beginPath();
  for (let i = 0; i < outerCrown.length; i++) {
    const [x, y] = k20Polar(outerCrown[i][0], outerCrown[i][1]);
    if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
  }
  for (let i = outerCrown.length - 1; i >= 0; i--) {
    const [x, y] = k20Polar(outerCrown[i][0], -outerCrown[i][1]);
    ctx.lineTo(x, y);
  }
  ctx.closePath();
  ctx.fillStyle = (k % 2 === 0) ? K20_PALETTE.turquoiseBright : K20_PALETTE.fuchsia;
  ctx.fill();

  /* Radial Word "JOY" cleanly isolated inside r in [0.163 .. 0.232] */
  const joyColor = (k % 2 === 0) ? K20_PALETTE.turquoiseBright : K20_PALETTE.turquoise;
  k20DrawWordCentered(ctx, 'JOY', 0.197, 0, 0.025, 0.18, joyColor);

  ctx.restore();
}

/* Outer Kaleidoscope Band Sector (r in [0.274..0.422], |theta| <= 13.5 deg) */
function k20DrawOuterSector(ctx, k, scale, alpha, morph) {
  if (scale <= 0.005 || alpha <= 0.005) return;
  const angle = -Math.PI * 0.5 + k * (K20_TAU / 12);
  const rMid = (K20_ZONES.band2MinR + K20_ZONES.band2MaxR) * 0.5;
  const rDrawMid = k20Lerp(K20_ZONES.band2MinR + 0.008, rMid, scale);
  const isEven = (k % 2) === 0;

  ctx.save();
  ctx.rotate(angle);
  ctx.globalAlpha *= alpha;
  ctx.translate(rDrawMid, 0);
  ctx.scale(scale, scale);
  ctx.translate(-rMid, 0);

  /* Side Kaleidoscope Mirror Shards strictly outside text theta <= 3 deg (occupies 6.2..11.8 deg) */
  const wingIn = 6.2 + morph * 1.4;
  const wingOut = 10.2 + morph * 2.2;
  k20FillSymmetricPolarPoly(
    ctx,
    [
      [0.296, wingIn],
      [0.348, wingOut],
      [0.398, wingIn],
      [0.348, wingIn - 0.8]
    ],
    isEven ? K20_PALETTE.turquoiseDeep : K20_PALETTE.fuchsiaDeep
  );

  /* Inner & Outer Crown Jewel Petals along Spoke Tip (strictly outside text radius 0.298..0.398) */
  const tipFlare = 5.5 + morph * 3.8;
  const outerJewel = [
    [0.402, 0.0],
    [0.410, tipFlare],
    [0.421, 0.0]
  ];
  ctx.beginPath();
  for (let i = 0; i < outerJewel.length; i++) {
    const [x, y] = k20Polar(outerJewel[i][0], outerJewel[i][1]);
    if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
  }
  for (let i = outerJewel.length - 1; i >= 0; i--) {
    const [x, y] = k20Polar(outerJewel[i][0], -outerJewel[i][1]);
    ctx.lineTo(x, y);
  }
  ctx.closePath();
  ctx.fillStyle = isEven ? K20_PALETTE.fuchsia : K20_PALETTE.turquoiseBright;
  ctx.fill();

  const innerAnchor = [
    [0.277, 0.0],
    [0.285, 4.8 + morph * 2.6],
    [0.293, 0.0]
  ];
  ctx.beginPath();
  for (let i = 0; i < innerAnchor.length; i++) {
    const [x, y] = k20Polar(innerAnchor[i][0], innerAnchor[i][1]);
    if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
  }
  for (let i = innerAnchor.length - 1; i >= 0; i--) {
    const [x, y] = k20Polar(innerAnchor[i][0], -innerAnchor[i][1]);
    ctx.lineTo(x, y);
  }
  ctx.closePath();
  ctx.fillStyle = isEven ? K20_PALETTE.fuchsiaBright : K20_PALETTE.turquoise;
  ctx.fill();

  /* Alternating Radial Typography: "CHEERS" (even spokes) & "2027" (odd spokes) */
  if (isEven) {
    k20DrawWordCentered(ctx, 'CHEERS', 0.348, 0, 0.0225, 0.16, K20_PALETTE.fuchsiaBright);
  } else {
    k20DrawWordCentered(ctx, '2027', 0.348, 0, 0.0285, 0.16, K20_PALETTE.turquoiseBright);
  }

  ctx.restore();
}

function k20DrawText(ctx, text, x, y, sizeU, weight, align, color, letterSpacingEm) {
  ctx.save();
  ctx.translate(x, y);
  ctx.scale(0.001, 0.001);
  ctx.fillStyle = color;
  ctx.textBaseline = 'middle';
  ctx.font = weight + ' ' + Math.round(sizeU * 1000) + 'px "Inter", "Plus Jakarta Sans", "Segoe UI", Arial, sans-serif';
  if (!letterSpacingEm || text.length <= 1) {
    ctx.textAlign = align;
    ctx.fillText(text, 0, 0);
  } else {
    const px = sizeU * 1000;
    const gap = letterSpacingEm * px;
    let totalW = 0;
    const ws = [];
    for (let i = 0; i < text.length; i++) {
      const w = ctx.measureText(text[i]).width;
      ws.push(w);
      totalW += w;
      if (i < text.length - 1) totalW += gap;
    }
    let cur = align === 'center' ? -totalW * 0.5 : (align === 'right' ? -totalW : 0);
    ctx.textAlign = 'left';
    for (let i = 0; i < text.length; i++) {
      ctx.fillText(text[i], cur, 0);
      cur += ws[i] + gap;
    }
  }
  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const safeLoopT = loopT < 0 ? loopT + duration : loopT;
  const st = k20EvaluateState(safeLoopT);
  const U = Math.min(height, width / (16 / 9));

  ctx.save();
  ctx.shadowBlur = 0;

  /* 1. Crisp Deep Architectural Teal Background (Zero Background Glow) */
  const bg = ctx.createLinearGradient(0, 0, 0, height);
  bg.addColorStop(0.0, K20_PALETTE.bgTop);
  bg.addColorStop(0.55, K20_PALETTE.bgMid);
  bg.addColorStop(1.0, K20_PALETTE.bgBot);
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, width, height);

  ctx.translate(width * 0.5, height * 0.5);
  ctx.scale(U, U);

  /* 2. Fixed Minimalist Outer Bezel & Corner Telemetry (Strictly Outside Mandala R = 0.442) */
  ctx.strokeStyle = K20_PALETTE.wireMuted;
  ctx.lineWidth = 0.0016;

  ctx.beginPath();
  ctx.arc(0, 0, K20_ZONES.outerBezelR, 0, K20_TAU);
  ctx.stroke();

  for (let tick = 0; tick < 12; tick++) {
    const a = -Math.PI * 0.5 + tick * (K20_TAU / 12);
    ctx.beginPath();
    ctx.moveTo(Math.cos(a) * K20_ZONES.outerBezelR, Math.sin(a) * K20_ZONES.outerBezelR);
    ctx.lineTo(Math.cos(a) * (K20_ZONES.outerBezelR + 0.009), Math.sin(a) * (K20_ZONES.outerBezelR + 0.009));
    ctx.strokeStyle = (tick % 2 === 0) ? K20_PALETTE.wireTurq : K20_PALETTE.wireFuch;
    ctx.stroke();
  }

  /* 3. Symmetric Drawing Divider Rings Growing Around 12 O'Clock Axis */
  if (st.arcSpanFrac > 0.005) {
    const halfSweep = st.arcSpanFrac * Math.PI;
    const rings = [
      { r: K20_ZONES.band1MinR - 0.004, col: K20_PALETTE.wireTurq },
      { r: K20_ZONES.band1MaxR + 0.005, col: K20_PALETTE.wireFuch },
      { r: K20_ZONES.band2MaxR + 0.004, col: K20_PALETTE.wireTurq }
    ];
    for (let i = 0; i < rings.length; i++) {
      ctx.beginPath();
      ctx.arc(0, 0, rings[i].r, -Math.PI * 0.5 - halfSweep, -Math.PI * 0.5 + halfSweep);
      ctx.strokeStyle = rings[i].col;
      ctx.lineWidth = 0.0018;
      ctx.stroke();
    }
  }

  /* 4. Band 1: Counter-Rotating Inner Kaleidoscope Ring ("JOY" + Turquoise Blades) */
  ctx.save();
  ctx.rotate(st.ringRotB);
  for (let k = 0; k < 12; k++) {
    k20DrawInnerSector(ctx, k, st.sectorBScale[k], st.sectorBAlpha[k], st.morph);
  }
  ctx.restore();

  /* 5. Band 2: Counter-Rotating Outer Kaleidoscope Ring ("CHEERS" + "2027" + Fuchsia Shards) */
  ctx.save();
  ctx.rotate(st.ringRotC);
  for (let k = 0; k < 12; k++) {
    k20DrawOuterSector(ctx, k, st.sectorCScale[k], st.sectorCAlpha[k], st.morph);
  }
  ctx.restore();

  /* 6. Central Core Medallion & Pulsing Hero "2027" */
  if (st.coreScale > 0.005 && st.coreAlpha > 0.005) {
    ctx.save();
    ctx.globalAlpha *= st.coreAlpha;
    ctx.scale(st.coreScale, st.coreScale);

    /* Crisp Dodecagonal Frame */
    ctx.beginPath();
    for (let i = 0; i < 12; i++) {
      const a = -Math.PI * 0.5 + i * (K20_TAU / 12);
      const r = (i % 2 === 0) ? K20_ZONES.coreRimOuter : K20_ZONES.coreRimInner;
      const x = Math.cos(a) * r;
      const y = Math.sin(a) * r;
      if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
    }
    ctx.closePath();
    ctx.fillStyle = K20_PALETTE.coreBg;
    ctx.fill();
    ctx.strokeStyle = K20_PALETTE.fuchsia;
    ctx.lineWidth = 0.0032;
    ctx.stroke();

    /* Subtle Concentric Inner Ring strictly inside Dodecagonal Rim */
    ctx.beginPath();
    ctx.arc(0, 0, K20_ZONES.coreRimInner - 0.018, 0, K20_TAU);
    ctx.strokeStyle = K20_PALETTE.wireTurq;
    ctx.lineWidth = 0.0014;
    ctx.stroke();

    k20DrawWordCentered(ctx, '2027', 0, 0, 0.048, 0.16, K20_PALETTE.turquoiseBright);
    ctx.restore();
  }

  ctx.restore();
}

