/* Smooth damped floor-contact bounce height (strictly >= 0 above floor, zero sinking below floor) */
function k17FloorBounceOffset(u) {
  if (u <= 0) return 1.0;
  if (u >= 1) return 0.0;
  if (u < 0.42) {
    const f = u / 0.42;
    return 1.0 - f * f;
  }
  if (u < 0.72) {
    const f = (u - 0.42) / 0.30;
    return Math.sin(Math.PI * f) * 0.24;
  }
  const f = (u - 0.72) / 0.28;
  return Math.sin(Math.PI * f) * 0.075;
}

function k17ContactSquash(u) {
  const b1 = Math.exp(-Math.pow((u - 0.42) / 0.055, 2)) * 0.085;
  const b2 = Math.exp(-Math.pow((u - 0.72) / 0.050, 2)) * 0.035;
  return b1 + b2;
}

function k17SampleCubic(p0, c1, c2, p1, steps) {
  const pts = [];
  for (let i = 1; i <= steps; i++) {
    const t = i / steps;
    const mt = 1 - t;
    const x = mt * mt * mt * p0[0] + 3 * mt * mt * t * c1[0] + 3 * mt * t * t * c2[0] + t * t * t * p1[0];
    const y = mt * mt * mt * p0[1] + 3 * mt * mt * t * c1[1] + 3 * mt * t * t * c2[1] + t * t * t * p1[1];
    pts.push([x, y]);
  }
  return pts;
}

function k17BuildSuperEllipseRing(cx, cy, rx, ry, power, steps) {
  const pts = [];
  for (let i = 0; i < steps; i++) {
    const a = (i / steps) * K17_TAU;
    const ca = Math.cos(a);
    const sa = Math.sin(a);
    pts.push([
      cx + Math.sign(ca) * Math.pow(Math.abs(ca), 2 / power) * rx,
      cy + Math.sign(sa) * Math.pow(Math.abs(sa), 2 / power) * ry
    ]);
  }
  return pts;
}

function k17DedupRing(pts) {
  const out = [];
  for (let i = 0; i < pts.length; i++) {
    const p = pts[i];
    if (out.length === 0) {
      out.push(p);
    } else {
      const prev = out[out.length - 1];
      if (Math.hypot(p[0] - prev[0], p[1] - prev[1]) > 1e-6) {
        out.push(p);
      }
    }
  }
  if (out.length > 2) {
    const first = out[0];
    const last = out[out.length - 1];
    if (Math.hypot(last[0] - first[0], last[1] - first[1]) <= 1e-6) {
      out.pop();
    }
  }
  return out;
}

