function k17LayoutRowChars(text, restY, h, gapRatio, rowIdx, colorShift) {
  const gap = h * gapRatio;
  const spaceW = h * 0.42;
  let totalW = 0;
  for (let i = 0; i < text.length; i++) {
    if (text[i] === ' ') {
      totalW += spaceW;
    } else {
      totalW += K17_GLYPHS[text[i]].w * h;
      if (i < text.length - 1 && text[i + 1] !== ' ') totalW += gap;
    }
  }

  let cursor = -totalW * 0.5;
  const out = [];
  let charSeq = 0;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (ch === ' ') {
      cursor += spaceW;
      continue;
    }
    const gw = K17_GLYPHS[ch].w * h;
    out.push({
      rowIdx,
      seqIdx: charSeq,
      ch,
      h,
      gw,
      restX: cursor + gw * 0.5,
      restY,
      color: K17_PALETTE.pastel[(charSeq + colorShift) % K17_PALETTE.pastel.length]
    });
    cursor += gw + gap;
    charSeq++;
  }
  return { rowIdx, totalW, h, restY, items: out };
}

