/* Unified State Evaluator across [0..20s] (shared by draw + collision assertions) */
function k17EvaluateState(loopT) {
  const duration = 20;
  const sceneCount = 4;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const safeScene = ((currentScene % sceneCount) + sceneCount) % sceneCount;
  const p = sceneProgress < 0 ? sceneProgress + 1 : sceneProgress;

  const letterStates = [];
  const confettiStates = [];
  let rowRuleFracs = [0, 0, 0];

  /* --- 1. Row 0: "HAPPY" (Scene 0 drop bounce -> holds cleanly -> lifts out FIRST at Scene 3 start) --- */
  const row0 = K17_ROWS[0].items;
  for (let i = 0; i < row0.length; i++) {
    const item = row0[i];
    let x = item.restX;
    let y = item.restY;
