    if (safeScene === 0) {
      const u = k17SubRange(p, 0.04 + i * 0.095, 0.56 + i * 0.095);
      const bounceH = k17FloorBounceOffset(u);
      const eHoriz = k17EaseOutCubic(k17SubRange(u, 0, 0.42));
      /* Order-preserving monotonic right-to-left parabolic sweep strictly below header */
      const arcHoriz = (1 - eHoriz) * 0.075;
      const sq = k17ContactSquash(u);
      x = item.restX + arcHoriz;
      y = item.restY - bounceH * 0.160;
      sx = 1 + sq;
      sy = 1 - sq * 0.85;
      rot = (1 - eHoriz) * 0.14;
