      const uOut = k17SubRange(p, 0.04 + i * 0.024, 0.26 + i * 0.024);
      const eOut = k17EaseInCubic(uOut);
      y = item.restY - eOut * 0.155;
      x = item.restX + (i - 2) * 0.012 * eOut;
      alpha = 1 - k17SubRange(uOut, 0.30, 0.95);
      rowRuleFracs[0] = 1 - k17EaseInCubic(k17SubRange(p, 0.12, 0.35));
