      rowIdx: 0,
      ch: item.ch,
      h: item.h,
      gw: item.gw,
      x,
      y,
      sx,
      sy,
      rot,
      alpha,
      color: item.color
    });
  }

  /* --- 2. Row 1: "NEW YEAR" (Horizontal-corridor pop & Sine Wave in Scene 1 -> lifts SECOND in Scene 3) --- */
  const row1 = K17_ROWS[1].items;
  for (let i = 0; i < row1.length; i++) {
    const item = row1[i];
    let x = item.restX;
    let y = item.restY;
    let sx = 1, sy = 1, rot = 0, alpha = 0;

    if (safeScene === 0) {
      alpha = 0;
      rowRuleFracs[1] = 0;
    } else if (safeScene === 1) {
      /* Enters along strictly order-preserving arc inside [-0.075 .. +0.035] lane */
      const uIn = k17SubRange(p, 0.03 + i * 0.042, 0.34 + i * 0.042);
      const eIn = k17EaseOutCubic(uIn);
      const archHop = Math.sin(Math.PI * eIn) * 0.020;
      x = k17Lerp(item.restX + 0.085, item.restX, eIn);
      y = item.restY - archHop;

      const waveEnv = Math.sin(Math.PI * k17SubRange(p, 0.28, 0.98));
      const wavePhase = (p - 0.28) * K17_TAU * 2.2 - i * 0.58;
      y += Math.sin(wavePhase) * 0.022 * waveEnv;
      rot = Math.cos(wavePhase) * 0.042 * waveEnv;
      alpha = k17Clamp01(uIn / 0.22);
      rowRuleFracs[1] = k17EaseOutCubic(k17SubRange(p, 0.05, 0.55));
    } else if (safeScene === 2) {
      rowRuleFracs[1] = 1;
      alpha = 1;
      const wavePhase = p * K17_TAU * 1.0 - i * 0.55;
      const gentleEnv = Math.sin(Math.PI * p);
      y = item.restY + Math.sin(wavePhase) * 0.008 * gentleEnv;
    } else {
      /* Exits SECOND cleanly upward (0.37..0.67) after HAPPY has cleared */
      const uOut = k17SubRange(p, 0.37 + i * 0.020, 0.55 + i * 0.020);
      const eOut = k17EaseInCubic(uOut);
      alpha = 1 - k17SubRange(uOut, 0.30, 0.95);
      y = item.restY - eOut * 0.24;
      rowRuleFracs[1] = 1 - k17EaseInCubic(k17SubRange(p, 0.42, 0.66));
    }

    letterStates.push({
      rowIdx: 1,
      ch: item.ch,
      h: item.h,
      gw: item.gw,
      x,
      y,
      sx,
      sy,
      rot,
      alpha,
      color: item.color
    });
  }

  /* --- 3. Row 2: "2027" (Arc launch from bottom in Scene 2 -> lifts THIRD in Scene 3) --- */
  const row2 = K17_ROWS[2].items;
  for (let i = 0; i < row2.length; i++) {
    const item = row2[i];
    let x = item.restX;
    let y = item.restY;
    let sx = 1, sy = 1, rot = 0, alpha = 0;

    if (safeScene === 0 || safeScene === 1) {
      alpha = 0;
      rowRuleFracs[2] = 0;
    } else if (safeScene === 2) {
      const uIn = k17SubRange(p, 0.03 + i * 0.065, 0.48 + i * 0.065);
      const eIn = k17EaseOutCubic(uIn);
      const yArch = Math.sin(Math.PI * k17Clamp01(uIn * 1.15)) * 0.025;
      x = k17Lerp(item.restX + 0.075, item.restX, eIn);
      /* Approaches cleanly from lower band y = +0.31 up to restY = +0.165 */
      y = k17Lerp(0.31, item.restY, eIn) - yArch;
      const pop = k17FloorBounceOffset(uIn) * 0.032;
      sx = 1 + pop * 0.5;
      sy = 1 - pop * 0.4;
      alpha = k17Clamp01(uIn / 0.16);
      rowRuleFracs[2] = k17EaseOutCubic(k17SubRange(p, 0.12, 0.62));
    } else {
      /* Exits THIRD cleanly upward (0.69..0.95) after NEW YEAR has cleared */
      const uOut = k17SubRange(p, 0.69 + i * 0.022, 0.89 + i * 0.022);
      const eOut = k17EaseInCubic(uOut);
      alpha = 1 - k17SubRange(uOut, 0.30, 0.95);
      y = item.restY - eOut * 0.28;
      rowRuleFracs[2] = 1 - k17EaseInCubic(k17SubRange(p, 0.72, 0.95));
    }

    letterStates.push({
      rowIdx: 2,
      ch: item.ch,
      h: item.h,
      gw: item.gw,
      x,
      y,
      sx,
      sy,
      rot,
      alpha,
      color: item.color
    });
  }

  /* --- 4. Confetti Physics (Bursts outward from flanks at Scene 2 0.24..1.0 -> Drifts downward & fades in Scene 3) --- */
  if (safeScene === 2 || safeScene === 3) {
    const tSinceBurst = (safeScene === 2)
      ? Math.max(0, (p - 0.22) * 5.0)
      : (3.90 + p * 5.0);

    for (let c = 0; c < K17_CONFETTI.length; c++) {
      const cf = K17_CONFETTI[c];
      const localT = tSinceBurst - cf.tOffset * 2.5;
      if (localT <= 0.005) continue;

      /* Burst phase [0..1.45s]: smooth drag-decelerated launch strictly outside center text zone */
      const burstU = k17Clamp01(localT / 1.45);
      const dragOut = 1 - Math.pow(1 - burstU, 2.4);

      let cx = k17Lerp(cf.startX, cf.peakX, dragOut);
      let cy = k17Lerp(cf.startY, cf.peakY, dragOut) - Math.sin(Math.PI * burstU) * 0.055;

      /* Settling gravity drift after burst apex */
      if (localT > 1.05) {
        const fallT = localT - 1.05;
        const fallFrac = k17Clamp01(fallT / 4.2);
        const smoothFall = fallFrac * fallFrac * (3 - 2 * fallFrac);
        cx += cf.fallDriftX * fallFrac + Math.sin(fallT * 2.1 + cf.idx) * 0.012 * fallFrac;
        cy += cf.fallDist * smoothFall;
      }

      /* Smooth fade-in at burst and crisp fade-out well before loop end t = 20s */
      const fadeIn = k17Clamp01(localT / 0.16);
      const fadeOut = (safeScene === 3) ? (1 - k17SubRange(p, 0.56, 0.90)) : 1.0;
      const alpha = fadeIn * fadeOut;
      if (alpha <= 0.01) continue;

      confettiStates.push({
        cx,
        cy,
        size: cf.size,
        shape: cf.shape,
        color: cf.color,
        rot: cf.spinInit + localT * cf.spinSpeed,
        flip: 0.35 + 0.65 * Math.abs(Math.cos(localT * cf.flipFreq + cf.idx)),
        alpha
      });
    }
  }

  return { safeScene, p, letterStates, confettiStates, rowRuleFracs };
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const safeLoopT = loopT < 0 ? loopT + duration : loopT;
  const st = k17EvaluateState(safeLoopT);

  const U = Math.min(height, width / (16 / 9));
  const halfW = (width / U) * 0.5;

  ctx.save();
  ctx.shadowBlur = 0;

  /* 1. Crisp Clean Studio White Matte Paper Ground (Zero Background Glow) */
  const bgGrad = ctx.createLinearGradient(0, 0, 0, height);
  bgGrad.addColorStop(0.0, K17_PALETTE.bgTop);
  bgGrad.addColorStop(0.55, K17_PALETTE.bgMid);
  bgGrad.addColorStop(1.0, K17_PALETTE.bgBot);
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);

  ctx.translate(width * 0.5, height * 0.5);
  ctx.scale(U, U);

  const fw = Math.min(halfW - 0.038, 0.815);
  const fh = 0.436;

  /* Top Header Pastel Palette Bar Indicators (Clean Non-Overlapping E-Commerce Chic) */
  const dotSpacing = 0.020;
  const dotStart = fw - 0.022 - 5 * dotSpacing;
  for (let i = 0; i < 6; i++) {
    ctx.beginPath();
    ctx.arc(dotStart + i * dotSpacing, -fh + 0.021, 0.0042, 0, K17_TAU);
    ctx.fillStyle = K17_PALETTE.pastel[i];
    ctx.fill();
  }

  /* 2. Grounding Horizontal Stage Rules Beneath Rows (Strict Separation From Letters) */
  const ruleYPositions = [-0.132, 0.032, 0.256];
  const ruleWidths = [0.23, 0.29, 0.25];
  for (let r = 0; r < 3; r++) {
    const frac = st.rowRuleFracs[r];
    if (frac <= 0.005) continue;
    const hw = ruleWidths[r] * frac;
    ctx.save();
    ctx.fillStyle = K17_PALETTE.guideLine;
    ctx.fillRect(-hw, ruleYPositions[r], hw * 2, 0.0018);
    ctx.restore();
  }

  /* 3. Render Pastel Typography Letters (Strict Non-Overlapping Lanes) */
  for (let i = 0; i < st.letterStates.length; i++) {
    const ls = st.letterStates[i];
    if (ls.alpha <= 0.005) continue;
    ctx.save();
    ctx.globalAlpha *= ls.alpha;
    ctx.translate(ls.x, ls.y);
    ctx.rotate(ls.rot);
    ctx.scale(ls.sx, ls.sy);
    k17DrawGlyphCentered(ctx, ls.ch, ls.h, ls.color);
    ctx.restore();
  }

  /* 4. Render Crisp Physics Confetti Pieces (Strictly Routed Outside Center Text Box) */
  for (let c = 0; c < st.confettiStates.length; c++) {
    const cf = st.confettiStates[c];
    ctx.save();
    ctx.globalAlpha *= cf.alpha;
    ctx.translate(cf.cx, cf.cy);
    ctx.rotate(cf.rot);
    ctx.scale(cf.flip, 1);
    ctx.fillStyle = cf.color;

    if (cf.shape === 0) {
      /* Rounded confetti streamer capsule */
      const w = cf.size * 1.45;
      const h = cf.size * 0.56;
      const r = h * 0.5;
      ctx.beginPath();
      ctx.moveTo(-w * 0.5 + r, -h * 0.5);
      ctx.lineTo(w * 0.5 - r, -h * 0.5);
      ctx.arc(w * 0.5 - r, 0, r, -Math.PI * 0.5, Math.PI * 0.5);
      ctx.lineTo(-w * 0.5 + r, h * 0.5);
      ctx.arc(-w * 0.5 + r, 0, r, Math.PI * 0.5, Math.PI * 1.5);
      ctx.closePath();
      ctx.fill();
    } else if (cf.shape === 1) {
      /* Sharp geometric diamond */
      const s = cf.size * 0.85;
      ctx.beginPath();
      ctx.moveTo(0, -s);
      ctx.lineTo(s * 0.72, 0);
      ctx.lineTo(0, s);
      ctx.lineTo(-s * 0.72, 0);
      ctx.closePath();
      ctx.fill();
    } else if (cf.shape === 2) {
      /* Crisp confetti disc */
      ctx.beginPath();
      ctx.arc(0, 0, cf.size * 0.55, 0, K17_TAU);
      ctx.fill();
    } else {
      /* Crisp equilateral confetti triangle */
      const s = cf.size * 0.90;
      ctx.beginPath();
      ctx.moveTo(0, -s * 0.78);
      ctx.lineTo(s * 0.72, s * 0.54);
      ctx.lineTo(-s * 0.72, s * 0.54);
      ctx.closePath();
      ctx.fill();
    }
    ctx.restore();
  }

  ctx.restore();
}

