function k18EaseOutCubic(t) {
  const u = 1 - k18Clamp01(t);
  return 1 - u * u * u;
}

function k18EaseInCubic(t) {
  const u = k18Clamp01(t);
  return u * u * u;
}

function k18EaseInOutCubic(t) {
  const u = k18Clamp01(t);
  return u < 0.5 ? 4 * u * u * u : 1 - Math.pow(-2 * u + 2, 3) / 2;
}

function k18EaseOutBackClean(t) {
  const u = k18Clamp01(t);
  if (u >= 1) return 1;
  const c1 = 1.18;
  const c3 = c1 + 1;
  return 1 + c3 * Math.pow(u - 1, 3) + c1 * Math.pow(u - 1, 2);
}

function k18SampleCubic(p0, c1, c2, p1, steps) {
  const pts = [];
  for (let i = 1; i <= steps; i++) {
    const t = i / steps;
    const mt = 1 - t;
    const x = mt * mt * mt * p0[0] + 3 * mt * mt * t * c1[0] + 3 * mt * t * t * c2[0] + t * t * t * p1[0];
    const y = mt * mt * mt * p0[1] + 3 * mt * mt * t * c1[1] + 3 * mt * t * t * c2[1] + t * t * t * p1[1];
    pts.push([x, y]);
  }
  return pts;
}

function k18BuildSuperEllipseRing(cx, cy, rx, ry, power, steps) {
  const pts = [];
  for (let i = 0; i < steps; i++) {
    const a = (i / steps) * K18_TAU;
    const ca = Math.cos(a);
    const sa = Math.sin(a);
    pts.push([
      cx + Math.sign(ca) * Math.pow(Math.abs(ca), 2 / power) * rx,
      cy + Math.sign(sa) * Math.pow(Math.abs(sa), 2 / power) * ry
    ]);
  }
  return pts;
}

function k18DedupRing(pts) {
  const out = [];
  for (let i = 0; i < pts.length; i++) {
    const p = pts[i];
    if (out.length === 0) {
      out.push(p);
    } else {
      const prev = out[out.length - 1];
      if (Math.hypot(p[0] - prev[0], p[1] - prev[1]) > 1e-6) {
        out.push(p);
      }
    }
  }
  if (out.length > 2) {
    const first = out[0];
    const last = out[out.length - 1];
    if (Math.hypot(last[0] - first[0], last[1] - first[1]) <= 1e-6) {
      out.pop();
    }
  }
  return out;
}

