/* Winding-number Point-In-Rings + Exact Segment Distance for 100% Strictly-Interior Halftone Dots */
function k18PointInRing(px, py, ring) {
  let inside = false;
  for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
    const xi = ring[i][0];
    const yi = ring[i][1];
    const xj = ring[j][0];
    const yj = ring[j][1];
    const intersect = ((yi > py) !== (yj > py)) &&
      (px < (xj - xi) * (py - yi) / ((yj - yi) || 1e-12) + xi);
    if (intersect) inside = !inside;
  }
  return inside;
}

function k18PointInGlyph(px, py, rings) {
  let parity = false;
  for (let r = 0; r < rings.length; r++) {
    if (k18PointInRing(px, py, rings[r])) parity = !parity;
  }
  return parity;
}

function k18DistPointToSeg(px, py, ax, ay, bx, by) {
  const vx = bx - ax;
  const vy = by - ay;
  const wx = px - ax;
  const wy = py - ay;
  const lenSq = vx * vx + vy * vy;
  let u = lenSq > 1e-12 ? (wx * vx + wy * vy) / lenSq : 0;
  if (u < 0) u = 0;
  else if (u > 1) u = 1;
  return Math.hypot(px - (ax + u * vx), py - (ay + u * vy));
}

function k18MinEdgeDistance(px, py, rings) {
  let best = 1e9;
  for (let r = 0; r < rings.length; r++) {
    const ring = rings[r];
    for (let i = 0; i < ring.length; i++) {
      const a = ring[i];
      const b = ring[(i + 1) % ring.length];
      const d = k18DistPointToSeg(px, py, a[0], a[1], b[0], b[1]);
      if (d < best) best = d;
    }
  }
  return best;
}

/* Precompute Strictly Interior Halftone Dots (guaranteed inside glyph outline with clear rim margin) */
const K18_DOT_MAX_R = 0.0225;
const K18_DOT_MIN_CLEAR = 0.0245;

const K18_GLYPH_DOTS = (function () {
  const out = {};
  const keys = Object.keys(K18_GLYPHS);
  const stepX = 0.056;
  const stepY = 0.056;
  for (let k = 0; k < keys.length; k++) {
    const ch = keys[k];
    const g = K18_GLYPHS[ch];
    const pts = [];
    for (let row = 0, vy = 0.036; vy <= 0.970; vy += stepY, row++) {
      const xOffset = (row % 2 === 1) ? stepX * 0.5 : 0;
      for (let vx = 0.034 + xOffset; vx <= g.w - 0.026; vx += stepX) {
        if (k18PointInGlyph(vx, vy, g.rings)) {
          const edgeD = k18MinEdgeDistance(vx, vy, g.rings);
          if (edgeD >= K18_DOT_MIN_CLEAR) {
            pts.push([vx, vy]);
          }
        }
      }
    }
    out[ch] = pts;
  }
  return out;
})();

/* Disjoint Fixed Specimen Grid Cells for "2027" and "NEW YEAR" */
const K18_CELLS = (function () {
  const cells = [];

  /* Upper Specimen Tier: "2027" */
  const topChars = ['2', '0', '2', '7'];
  const topH = 0.185;
  const topCellW = 0.232;
  const topGap = 0.034;
  const topFrameH = 0.246;
  const topCy = -0.105;
  const topTotalW = topChars.length * topCellW + (topChars.length - 1) * topGap;
  let curX = -topTotalW * 0.5;

  for (let i = 0; i < topChars.length; i++) {
    const ch = topChars[i];
    cells.push({
      idx: i,
      tier: 0,
      ch,
      cx: curX + topCellW * 0.5,
      cy: topCy,
      h: topH,
      gw: K18_GLYPHS[ch].w * topH,
      cellW: topCellW,
      frameW: topCellW - 0.012,
      frameH: topFrameH,
      slotCode: 'G-0' + (i + 1)
    });
    curX += topCellW + topGap;
  }

  /* Lower Specimen Tier: "NEW YEAR" */
  const botChars = ['N', 'E', 'W', 'Y', 'E', 'A', 'R'];
  const botH = 0.100;
  const botCellW = 0.148;
  const botGap = 0.022;
  const botWordExtra = 0.060;
  const botFrameH = 0.144;
  const botCy = 0.185;
  const botTotalW = botChars.length * botCellW + (botChars.length - 1) * botGap + botWordExtra;
  curX = -botTotalW * 0.5;

  for (let j = 0; j < botChars.length; j++) {
    const ch = botChars[j];
    cells.push({
      idx: 4 + j,
      tier: 1,
      ch,
      cx: curX + botCellW * 0.5,
      cy: botCy,
      h: botH,
      gw: K18_GLYPHS[ch].w * botH,
      cellW: botCellW,
      frameW: botCellW - 0.008,
      frameH: botFrameH,
      slotCode: 'L-0' + (j + 1)
    });
    curX += botCellW + botGap + (j === 2 ? botWordExtra : 0);
  }

  return cells;
})();

const K18_MIXED_INIT_STYLES = [0, 2, 4, 1, 3, 0, 4, 2, 1, 3, 0];
const K18_SCENE1_SEQ = [
  [0, 3, 1, 4],
  [2, 4, 0, 1],
  [4, 1, 3, 2],
  [1, 0, 2, 3],
  [3, 2, 4, 0],
  [0, 4, 1, 2],
  [4, 2, 0, 3],
  [2, 1, 4, 0],
  [1, 3, 2, 4],
  [3, 0, 1, 2],
  [0, 2, 3, 1]
];
const K18_MIXED_EXIT_STYLES = [4, 2, 0, 1, 2, 4, 1, 0, 3, 2, 4];

/* Smooth Single Style-Swap Squash Envelope: u in [0..1], switches style cleanly at max compression u = 0.5 */
function k18SwapEnvelope(u) {
  const cu = k18Clamp01(u);
  if (cu <= 0 || cu >= 1) {
    return { sx: 1, sy: 1, useNext: cu >= 0.5 };
  }
  const useNext = cu >= 0.5;
  /* Peak squash at cu = 0.50: sy = 0.72, sx = 1.12 (strictly bounded inside specimen cell width) */
  let comp;
  if (cu < 0.5) {
    const f = cu / 0.5;
    comp = f * f * (3 - 2 * f);
  } else {
    const f = (cu - 0.5) / 0.5;
    const inv = 1 - f;
    comp = inv * inv * (3 - 2 * inv);
  }
  return {
    sx: 1 + 0.12 * comp,
    sy: 1 - 0.28 * comp,
    useNext
  };
}

function k18EvaluateGlyphStates(loopT) {
  const duration = 20;
  const sceneCount = 4;
  const sceneDuration = duration / sceneCount;
  const safeScene = Math.max(0, Math.min(3, Math.floor(loopT / sceneDuration)));
  const p = (loopT % sceneDuration) / sceneDuration;
  const items = [];

  for (let idx = 0; idx < K18_CELLS.length; idx++) {
    const cell = K18_CELLS[idx];
    let styleIdx = K18_MIXED_INIT_STYLES[idx];
    let scale = 1;
    let sx = 1;
    let sy = 1;
    let alpha = 1;

    if (safeScene === 0) {
      /* Scene 0: Specimen Reveal & Pop-In in Mixed Initial Styles */
      const start = 0.04 + idx * 0.045;
      const u = k18SubRange(p, start, start + 0.28);
      if (u <= 0) {
        scale = 0;
        alpha = 0;
      } else {
        const pop = k18EaseOutBackClean(u);
        scale = k18Clamp01(pop > 1.04 ? 1.04 : pop);
        alpha = k18Clamp01(u / 0.30);
        const bounce = Math.sin(u * Math.PI) * (1 - u) * 0.08;
        sx = 1 + bounce * 0.8;
        sy = 1 - bounce;
      }
      styleIdx = K18_MIXED_INIT_STYLES[idx];
    } else if (safeScene === 1) {
      /* Scene 1: Staggered Independent Per-Letter Style Cycling with Squash Snaps */
      const seq = K18_SCENE1_SEQ[idx];
      const baseOff = (idx * 0.038) % 0.14;
      const winDur = 0.24;
      const windows = [0.04 + baseOff, 0.34 + baseOff * 0.7, 0.64 + baseOff * 0.5];
      styleIdx = seq[0];
      for (let w = 0; w < windows.length; w++) {
        const wStart = windows[w];
        const wEnd = wStart + winDur;
        if (p >= wEnd) {
          styleIdx = seq[w + 1];
        } else if (p > wStart) {
          const u = (p - wStart) / winDur;
          const env = k18SwapEnvelope(u);
          sx = env.sx;
          sy = env.sy;
          styleIdx = env.useNext ? seq[w + 1] : seq[w];
          break;
        }
      }
    } else if (safeScene === 2) {
      /* Scene 2: Left-to-Right Snap into Unified SERIF, then Collective Beat Pulse into Animated DOTS */
      const s1End = K18_SCENE1_SEQ[idx][3];
      const uniStart = 0.06 + idx * 0.025;
      const uniEnd = uniStart + 0.16;

      if (p < 0.50) {
        if (p <= uniStart) {
          styleIdx = s1End;
        } else if (p < uniEnd) {
          const u = (p - uniStart) / (uniEnd - uniStart);
          const env = k18SwapEnvelope(u);
          sx = env.sx;
          sy = env.sy;
          styleIdx = env.useNext ? 0 : s1End; /* Snap to SERIF (0) */
        } else {
          styleIdx = 0;
        }
      } else {
        /* Collective synchronous beat squash across all 11 glyphs at p = 0.54..0.78 into DOTS (3) */
        const beatU = k18SubRange(p, 0.54, 0.78);
        if (beatU <= 0) {
          styleIdx = 0;
        } else if (beatU < 1) {
          const env = k18SwapEnvelope(beatU);
          sx = env.sx;
          sy = env.sy;
          styleIdx = env.useNext ? 3 : 0; /* Snap all glyphs together into DOTS (3) */
        } else {
          styleIdx = 3;
        }
      }
    } else {
      /* Scene 3: Break Back Apart into Mixed Styles -> Clean Staggered Scale Retraction to t = 0 Seam */
      const breakStart = 0.06 + ((10 - idx) * 0.022);
      const breakEnd = breakStart + 0.18;
      const exitStyle = K18_MIXED_EXIT_STYLES[idx];

      if (p < 0.54) {
        if (p <= breakStart) {
          styleIdx = 3;
        } else if (p < breakEnd) {
          const u = (p - breakStart) / (breakEnd - breakStart);
          const env = k18SwapEnvelope(u);
          sx = env.sx;
          sy = env.sy;
          styleIdx = env.useNext ? exitStyle : 3;
        } else {
          styleIdx = exitStyle;
        }
      } else {
        styleIdx = exitStyle;
        const retStart = 0.56 + idx * 0.024;
        const u = k18SubRange(p, retStart, retStart + 0.14);
        if (u >= 1) {
          scale = 0;
          alpha = 0;
        } else if (u > 0) {
          const ease = k18EaseInCubic(u);
          scale = 1 - ease;
          alpha = 1 - k18Clamp01(u / 0.85);
          sx = 1 + ease * 0.06;
          sy = 1 - ease * 0.14;
        }
      }
    }

    items.push({
      idx,
      cell,
      styleIdx,
      scale,
      sx,
      sy,
      alpha,
      dotPhaseOffset: idx * 0.55
    });
  }

  return { safeScene, p, items };
}

function k18TraceGlyphRings(ctx, rings, h) {
  ctx.beginPath();
  for (let r = 0; r < rings.length; r++) {
    const pts = rings[r];
    if (pts.length < 3) continue;
    ctx.moveTo(pts[0][0] * h, pts[0][1] * h);
    for (let i = 1; i < pts.length; i++) {
      ctx.lineTo(pts[i][0] * h, pts[i][1] * h);
    }
    ctx.closePath();
  }
}

/* Crisp Editorial Typography Renderer via 0.001 Scale Strategy */
function k18DrawText(ctx, text, x, y, sizeU, weight, align, color, letterSpacingEm) {
  ctx.save();
  ctx.translate(x, y);
  ctx.scale(0.001, 0.001);
  ctx.fillStyle = color;
  ctx.textBaseline = 'middle';
  ctx.font = weight + ' ' + Math.round(sizeU * 1000) + 'px "Inter", "Plus Jakarta Sans", "Segoe UI", Arial, sans-serif';
  if (!letterSpacingEm || text.length <= 1) {
    ctx.textAlign = align;
    ctx.fillText(text, 0, 0);
  } else {
    const px = sizeU * 1000;
    const gap = letterSpacingEm * px;
    let totalW = 0;
    const ws = [];
    for (let i = 0; i < text.length; i++) {
      const w = ctx.measureText(text[i]).width;
      ws.push(w);
      totalW += w;
      if (i < text.length - 1) totalW += gap;
    }
    let cur = align === 'center' ? -totalW * 0.5 : (align === 'right' ? -totalW : 0);
    ctx.textAlign = 'left';
    for (let i = 0; i < text.length; i++) {
      ctx.fillText(text[i], cur, 0);
      cur += ws[i] + gap;
    }
  }
  ctx.restore();
}

/* 5 Distinct Crisp Vector Glyph Style Renderers */
function k18DrawStyledGlyph(ctx, item, loopT) {
  const { cell, styleIdx, scale, sx, sy, alpha, dotPhaseOffset } = item;
  if (scale <= 0.001 || alpha <= 0.001) return;

  const glyph = K18_GLYPHS[cell.ch];
  const h = cell.h;
  const gw = cell.gw;

  ctx.save();
  ctx.globalAlpha = alpha;
  ctx.translate(cell.cx, cell.cy);
  ctx.scale(scale * sx, scale * sy);
  ctx.translate(-gw * 0.5, -h * 0.5);

  if (styleIdx === 0) {
    /* STYLE 0: SERIF — Soft Pink Solid Body + Geometric Didone Serif Slabs & Fine Inline Accent */
    ctx.fillStyle = K18_PALETTE.pink;
    for (let s = 0; s < glyph.serifs.length; s++) {
      const sr = glyph.serifs[s];
      ctx.fillRect(sr[0] * h, sr[1] * h, (sr[2] - sr[0]) * h, (sr[3] - sr[1]) * h);
    }
    k18TraceGlyphRings(ctx, glyph.rings, h);
    ctx.fill('evenodd');

    ctx.strokeStyle = K18_PALETTE.pinkBright;
    ctx.lineWidth = 0.015 * h;
    ctx.lineCap = 'butt';
    for (let l = 0; l < glyph.inlineSegs.length; l++) {
      const seg = glyph.inlineSegs[l];
      ctx.beginPath();
      ctx.moveTo(seg[0][0] * h, seg[0][1] * h);
      ctx.lineTo(seg[1][0] * h, seg[1][1] * h);
      ctx.stroke();
    }
  } else if (styleIdx === 1) {
    /* STYLE 1: MONO — Technical Ice-Lavender Body + Precision Caliper Brackets & Spine Axis */
    ctx.fillStyle = K18_PALETTE.ice;
    k18TraceGlyphRings(ctx, glyph.rings, h);
    ctx.fill('evenodd');

    /* Inner modular technical spine line */
    ctx.strokeStyle = K18_PALETTE.bgMid;
    ctx.lineWidth = 0.022 * h;
    ctx.lineCap = 'butt';
    for (let l = 0; l < glyph.inlineSegs.length; l++) {
      const seg = glyph.inlineSegs[l];
      ctx.beginPath();
      ctx.moveTo(seg[0][0] * h, seg[0][1] * h);
      ctx.lineTo(seg[1][0] * h, seg[1][1] * h);
      ctx.stroke();
    }

    /* Fixed-width monospace caliper brackets flanking left & right bounds */
    const bPad = 0.055 * h;
    const arm = 0.14 * h;
    ctx.strokeStyle = K18_PALETTE.periwinkle;
    ctx.lineWidth = 0.024 * h;
    ctx.lineCap = 'square';
    ctx.beginPath();
    ctx.moveTo(-bPad + arm, 0);
    ctx.lineTo(-bPad, 0);
    ctx.lineTo(-bPad, h);
    ctx.lineTo(-bPad + arm, h);
    ctx.moveTo(gw + bPad - arm, 0);
    ctx.lineTo(gw + bPad, 0);
    ctx.lineTo(gw + bPad, h);
    ctx.lineTo(gw + bPad - arm, h);
    ctx.stroke();
  } else if (styleIdx === 2) {
    /* STYLE 2: OUTLINE — Hollow Architectural Double-Contour + Anchor Node Squares */
    ctx.strokeStyle = K18_PALETTE.pink;
    ctx.lineWidth = 0.050 * h;
    ctx.lineJoin = 'round';
    k18TraceGlyphRings(ctx, glyph.rings, h);
    ctx.stroke();

    ctx.strokeStyle = K18_PALETTE.bgMid;
    ctx.lineWidth = 0.020 * h;
    ctx.lineJoin = 'round';
    ctx.stroke();

    ctx.strokeStyle = K18_PALETTE.pinkBright;
    ctx.lineWidth = 0.012 * h;
    ctx.stroke();

    /* Crisp vector corner control nodes */
    const nodeSz = 0.048 * h;
    ctx.fillStyle = K18_PALETTE.ice;
    for (let n = 0; n < glyph.nodes.length; n++) {
      const pt = glyph.nodes[n];
      ctx.fillRect(pt[0] * h - nodeSz * 0.5, pt[1] * h - nodeSz * 0.5, nodeSz, nodeSz);
    }
  } else if (styleIdx === 3) {
    /* STYLE 3: DOTS — Strictly-Interior Animated Halftone Lattice (Zero Border Clipping) */
    const dots = K18_GLYPH_DOTS[cell.ch];
    const wavePhase = loopT * K18_TAU * 0.5 + dotPhaseOffset;

    /* Crisp subtle structural anchor corners at glyph bounds */
    ctx.strokeStyle = 'rgba(143, 168, 255, 0.36)';
    ctx.lineWidth = 0.014 * h;
    ctx.beginPath();
    ctx.moveTo(0, 0.09 * h);
    ctx.lineTo(0, 0);
    ctx.lineTo(0.09 * h, 0);
    ctx.moveTo(gw - 0.09 * h, h);
    ctx.lineTo(gw, h);
    ctx.lineTo(gw, h - 0.09 * h);
    ctx.stroke();

    for (let d = 0; d < dots.length; d++) {
      const u = dots[d][0];
      const v = dots[d][1];
      const pulse = 0.5 + 0.5 * Math.sin(wavePhase - u * 5.2 - v * 4.4);
      const r = h * K18_DOT_MAX_R * (0.68 + 0.32 * pulse);
      ctx.fillStyle = pulse > 0.55 ? K18_PALETTE.pinkBright : K18_PALETTE.pink;
      ctx.beginPath();
      ctx.arc(u * h, v * h, r, 0, K18_TAU);
      ctx.fill();
    }
  } else {
    /* STYLE 4: STENCIL — Clean Precision Stencil via Even-Odd Clip Bridges */
    const slW = gw + 0.24 * h;
    const g1Top = 0.315 * h;
    const g1H = 0.062 * h;
    const g2Top = 0.665 * h;
    const g2H = 0.062 * h;

    ctx.save();
    ctx.beginPath();
    ctx.rect(-0.12 * h, -0.06 * h, slW, g1Top + 0.06 * h);
    ctx.rect(-0.12 * h, g1Top + g1H, slW, g2Top - (g1Top + g1H));
    ctx.rect(-0.12 * h, g2Top + g2H, slW, h - (g2Top + g2H) + 0.06 * h);
    ctx.clip();

    ctx.fillStyle = K18_PALETTE.pinkDeep;
    k18TraceGlyphRings(ctx, glyph.rings, h);
    ctx.fill('evenodd');

    /* Crisp upper-highlight bevel edge inside stencil bands */
    ctx.strokeStyle = K18_PALETTE.pinkBright;
    ctx.lineWidth = 0.015 * h;
    ctx.stroke();
    ctx.restore();

    /* Delicate stencil alignment cut-marks flanking left/right gap channels */
    ctx.fillStyle = K18_PALETTE.periwinkle;
    ctx.fillRect(-0.045 * h, g1Top + g1H * 0.38, 0.032 * h, g1H * 0.24);
    ctx.fillRect(gw + 0.013 * h, g1Top + g1H * 0.38, 0.032 * h, g1H * 0.24);
    ctx.fillRect(-0.045 * h, g2Top + g2H * 0.38, 0.032 * h, g2H * 0.24);
    ctx.fillRect(gw + 0.013 * h, g2Top + g2H * 0.38, 0.032 * h, g2H * 0.24);
  }

  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  ctx.save();
  ctx.shadowBlur = 0;

  /* 1. Electric Ultramarine Vertical Gradient Background (Zero Radial Glow) */
  const bg = ctx.createLinearGradient(0, 0, 0, height);
  bg.addColorStop(0.0, K18_PALETTE.bgTop);
  bg.addColorStop(0.55, K18_PALETTE.bgMid);
  bg.addColorStop(1.0, K18_PALETTE.bgBot);
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, width, height);

  /* Normalized Unit Coordinate Frame: Origin at Canvas Center, Scale = height */
  ctx.translate(width * 0.5, height * 0.5);
  ctx.scale(height, height);

  /* 2. Architectural Swiss Specimen Hairline Grid */
  ctx.strokeStyle = K18_PALETTE.cobaltRule;
  ctx.lineWidth = 0.0022;

  /* Crisp Horizontal Header & Footer Divider Rules (Strictly Outside Specimen Zones) */
  ctx.beginPath();
  ctx.moveTo(-0.75, -0.345);
  ctx.lineTo(0.75, -0.345);
  ctx.moveTo(-0.75, 0.068);
  ctx.lineTo(0.75, 0.068);
  ctx.moveTo(-0.75, 0.335);
  ctx.lineTo(0.75, 0.335);
  ctx.stroke();

  /* 3. Evaluate & Draw Each Specimen Frame + Crisp Live Styled Glyph */
  const state = k18EvaluateGlyphStates(loopT);
  const styleCounts = [0, 0, 0, 0, 0];

  for (let i = 0; i < state.items.length; i++) {
    const item = state.items[i];
    const cell = item.cell;

    if (item.alpha > 0.25) {
      styleCounts[item.styleIdx]++;
    }

    /* Fixed Specimen Cell Box & Index Header */
    ctx.strokeStyle = item.alpha > 0.1 ? K18_PALETTE.cobaltDim : K18_PALETTE.cobaltFaint;
    ctx.lineWidth = 0.0018;
    ctx.strokeRect(
      cell.cx - cell.frameW * 0.5,
      cell.cy - cell.frameH * 0.5,
      cell.frameW,
      cell.frameH
    );

