function k15MeasureTextWidth(str, h, gapRatio, spaceRatio) {
  let w = 0;
  for (let i = 0; i < str.length; i++) {
    const ch = str[i];
    if (ch === ' ') {
      w += h * (spaceRatio || 0.36);
    } else {
      w += K15_GLYPHS[ch].w * h;
    }
    if (i < str.length - 1 && str[i] !== ' ' && str[i + 1] !== ' ') {
      w += h * gapRatio;
    }
  }
  return w;
}

function k15DrawGlyph(ctx, ch, x, y, h, fillStyle) {
  const g = K15_GLYPHS[ch];
  ctx.beginPath();
  for (let r = 0; r < g.rings.length; r++) {
    const ring = g.rings[r];
    ctx.moveTo(x + ring[0][0] * h, y + ring[0][1] * h);
    for (let k = 1; k < ring.length; k++) {
      ctx.lineTo(x + ring[k][0] * h, y + ring[k][1] * h);
    }
    ctx.closePath();
  }
  ctx.fillStyle = fillStyle;
  ctx.fill('evenodd');
}

function k15DrawVectorWord(ctx, str, startX, topY, h, gapRatio, spaceRatio, fillStyle, charOffsetsY) {
  let cursor = startX;
  for (let i = 0; i < str.length; i++) {
    const ch = str[i];
    if (ch === ' ') {
      cursor += h * (spaceRatio || 0.36);
      continue;
    }
    const g = K15_GLYPHS[ch];
    const dy = charOffsetsY ? (charOffsetsY[i] || 0) : 0;
    k15DrawGlyph(ctx, ch, cursor, topY + dy, h, fillStyle);
    cursor += g.w * h;
    if (i < str.length - 1 && str[i + 1] !== ' ') {
      cursor += h * gapRatio;
    }
  }
}

