    }
  } else {
    /* SCENE 3 (15 - 20s): Words slide up behind clip masks, windows shut cleanly, grid retracts to t=0 seam */
    const uHelloOut = k15EaseInCubic(k15SubRange(p, 0.00, 0.32));
    wordSlideY.hello = k15Lerp(0, -0.22, uHelloOut);
    helloAlpha = 1 - k15SubRange(p, 0.22, 0.34);

    yearAlpha = 1 - k15SubRange(p, 0.30, 0.42);
    for (let d = 0; d < 4; d++) {
      const udOut = k15EaseInCubic(k15SubRange(p, 0.04 + d * 0.032, 0.34 + d * 0.032));
      yearDigitOffsetsY[d] = k15Lerp(0, -0.28, udOut);
    }

    for (let k = 0; k < 3; k++) {
      const ukOut = k15EaseInCubic(k15SubRange(p, 0.06 + k * 0.045, 0.36 + k * 0.045));
      hopeSlideY[k] = k15Lerp(0, -0.16, ukOut);
      hopeWordAlpha[k] = 1 - k15SubRange(p, 0.26 + k * 0.04, 0.38 + k * 0.04);
    }

    const uBannerOut = k15EaseInCubic(k15SubRange(p, 0.12, 0.44));
    wordSlideY.banner = k15Lerp(0, -0.16, uBannerOut);
    bannerAlpha = 1 - k15SubRange(p, 0.34, 0.46);
    wordSlideY.status = k15Lerp(0, -0.14, k15EaseInCubic(k15SubRange(p, 0.14, 0.44)));
    wordSlideY.mast = k15Lerp(0, -0.055, k15EaseInCubic(k15SubRange(p, 0.20, 0.48)));

    winOpen = {
      status: 1 - k15EaseInOutCubic(k15SubRange(p, 0.36, 0.64)),
      banner: 1 - k15EaseInOutCubic(k15SubRange(p, 0.38, 0.68)),
      hope: 1 - k15EaseInOutCubic(k15SubRange(p, 0.40, 0.70)),
      growth: 1 - k15EaseInOutCubic(k15SubRange(p, 0.44, 0.74)),
      joy: 1 - k15EaseInOutCubic(k15SubRange(p, 0.48, 0.76)),
      year: 1 - k15EaseInOutCubic(k15SubRange(p, 0.50, 0.80)),
      hello: 1 - k15EaseInOutCubic(k15SubRange(p, 0.54, 0.82)),
      mast: 1 - k15EaseInOutCubic(k15SubRange(p, 0.58, 0.86))
    };

    gridDraw = 1 - k15EaseInOutCubic(k15SubRange(p, 0.64, 0.96));
  }

  return {
    safeScene,
    p,
    gridDraw,
    winOpen,
    wordSlideY,
    yearDigitOffsetsY,
    hopeSlideY,
    hopeWordAlpha,
    helloAlpha,
    yearAlpha,
    bannerAlpha,
    highlightWipes,
    yearBreath,
    activeKeywordIdx
  };
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const safeLoopT = loopT < 0 ? loopT + duration : loopT;
  const tl = k15EvaluateTimeline(safeLoopT);

  const U = Math.min(height, width / (16 / 9));
  const halfW = (width / U) * 0.5;

  ctx.save();
  ctx.shadowBlur = 0;

  /* 1. Crisp Architectural Sand-Beige Editorial Paper Surface (Zero background glow) */
  const bgGrad = ctx.createLinearGradient(0, 0, width * 0.35, height);
  bgGrad.addColorStop(0.0, K15_PALETTE.bgTop);
  bgGrad.addColorStop(0.52, K15_PALETTE.bgMid);
  bgGrad.addColorStop(1.0, K15_PALETTE.bgBot);
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);

  ctx.translate(width * 0.5, height * 0.5);
  ctx.scale(U, U);

  /* 2. Editorial Structural Blueprint Grid Rules */
  if (tl.gridDraw > 0.002) {
    const gxSpan = 0.765 * tl.gridDraw;
    const gyTop = -0.390;
    const gyBot = 0.376;
    const gyHalf = ((gyBot - gyTop) * 0.5) * tl.gridDraw;
    const gyMid = (gyTop + gyBot) * 0.5;

    ctx.save();
    ctx.strokeStyle = K15_PALETTE.gridRule;
    ctx.lineWidth = 0.0015;
    ctx.beginPath();
    const yLines = [-0.390, -0.328, -0.304, -0.109, -0.084, 0.206, 0.230, 0.376];
    for (let i = 0; i < yLines.length; i++) {
      ctx.moveTo(-gxSpan, yLines[i]);
      ctx.lineTo(gxSpan, yLines[i]);
    }
    const xLines = [-0.765, -0.036, -0.004, 0.328, 0.352, 0.765];
    for (let i = 0; i < xLines.length; i++) {
      ctx.moveTo(xLines[i], gyMid - gyHalf);
      ctx.lineTo(xLines[i], gyMid + gyHalf);
    }
    ctx.stroke();
    ctx.restore();
  }

  /* 3. Window 1: Top Masthead Window */
  const wMast = K15_WINDOWS.mast;
  if (k15DrawWindowFrame(ctx, wMast, tl.winOpen.mast, K15_PALETTE.cardWarm, K15_PALETTE.inkBlack, 0.0018)) {
    const mastLabelAlpha = k15Clamp01((tl.winOpen.mast - 0.45) / 0.50);
    if (mastLabelAlpha > 0.01) {
      ctx.save();
      ctx.beginPath();
      ctx.rect(wMast.x, wMast.y, wMast.w * tl.winOpen.mast, wMast.h);
      ctx.clip();
      ctx.globalAlpha *= mastLabelAlpha;

      const my = wMast.y + wMast.h * 0.5 + tl.wordSlideY.mast;
      k15DrawEditorialText(ctx, 'NO. 27  •  NEW YEAR ANNUAL FOLIO', wMast.x + 0.026, my, 0.0175, '700', '"Segoe UI", "Helvetica Neue", Arial, sans-serif', K15_PALETTE.inkBlack, 'left', 'middle');

      const pillW = 0.145;
      const pillH = 0.032;
      const pillX = wMast.x + wMast.w - 0.024 - pillW;
      ctx.fillStyle = K15_PALETTE.forestDeep;
      ctx.fillRect(pillX, my - pillH * 0.5, pillW, pillH);
      k15DrawEditorialText(ctx, 'EDITION 2027', pillX + pillW * 0.5, my, 0.0145, '700', '"Segoe UI", "Helvetica Neue", Arial, sans-serif', K15_PALETTE.creamBright, 'center', 'middle');
      ctx.restore();
    }
  }

  /* 4. Window 2: Upper-Left "HELLO" Window (Sub-Clip Strictly Below Header Caption) */
  const wHello = K15_WINDOWS.hello;
  if (k15DrawWindowFrame(ctx, wHello, tl.winOpen.hello, K15_PALETTE.cardWarm, K15_PALETTE.inkBlack, 0.0020)) {
    const visHelloW = wHello.w * tl.winOpen.hello;
    const helloCapAlpha = k15Clamp01((tl.winOpen.hello - 0.45) / 0.50);
    if (helloCapAlpha > 0.01) {
      ctx.save();
      ctx.beginPath();
      ctx.rect(wHello.x, wHello.y, visHelloW, wHello.h);
      ctx.clip();
      ctx.globalAlpha *= helloCapAlpha;
      k15DrawEditorialText(ctx, '00  //  OPENING SALUTATION', wHello.x + 0.026, wHello.y + 0.024, 0.0135, '700', '"Segoe UI", "Helvetica Neue", Arial, sans-serif', K15_PALETTE.forestMid, 'left', 'middle');
      ctx.restore();
    }

    if (tl.helloAlpha > 0.005) {
      const hHello = 0.112;
      const wWord = k15MeasureTextWidth('HELLO', hHello, 0.16, 0.36);
      const startX = wHello.x + (wHello.w - wWord) * 0.5;
      const topY = wHello.y + 0.056 + tl.wordSlideY.hello;

      ctx.save();
      ctx.beginPath();
      ctx.rect(wHello.x, wHello.y + 0.042, visHelloW, wHello.h - 0.042);
      ctx.clip();
      ctx.globalAlpha *= tl.helloAlpha;
      k15DrawVectorWord(ctx, 'HELLO', startX, topY, hHello, 0.16, 0.36, K15_PALETTE.inkBlack, null);
      ctx.restore();
    }
  }

  /* 5. Window 3: Lower-Left Forest Green "2027" Feature Window (Sub-Clip Strictly Above Bottom Chronicle Caption) */
  const wYear = K15_WINDOWS.year;
  if (k15DrawWindowFrame(ctx, wYear, tl.winOpen.year, K15_PALETTE.forestDeep, K15_PALETTE.inkBlack, 0.0020)) {
    const visYearW = wYear.w * tl.winOpen.year;
    const inset = 0.012;
    ctx.save();
    ctx.beginPath();
    ctx.rect(wYear.x, wYear.y, visYearW, wYear.h);
    ctx.clip();

    ctx.strokeStyle = 'rgba(212, 194, 160, 0.42)';
    ctx.lineWidth = 0.0014;
    ctx.strokeRect(wYear.x + inset, wYear.y + inset, wYear.w - inset * 2, wYear.h - inset * 2);

    const yearCapAlpha = k15Clamp01((tl.winOpen.year - 0.45) / 0.50);
    if (yearCapAlpha > 0.01) {
      ctx.save();
      ctx.globalAlpha *= yearCapAlpha;
      k15DrawEditorialText(ctx, 'TWENTY TWENTY-SEVEN  •  CHRONICLE', wYear.x + wYear.w * 0.5, wYear.y + wYear.h - 0.030, 0.0135, '700', '"Segoe UI", "Helvetica Neue", Arial, sans-serif', K15_PALETTE.sandGold, 'center', 'middle');
      ctx.restore();
    }
    ctx.restore();

    if (tl.yearAlpha > 0.005 && visYearW > inset * 2) {
      const hYear = 0.168 * tl.yearBreath;
      const wYearWord = k15MeasureTextWidth('2027', hYear, 0.17, 0.36);
      const cxYear = wYear.x + wYear.w * 0.5;
      const cyYear = wYear.y + 0.120;
      const startX = cxYear - wYearWord * 0.5;
      const topY = cyYear - hYear * 0.5;

      ctx.save();
      ctx.beginPath();
      ctx.rect(wYear.x + inset, wYear.y + inset, Math.max(0, visYearW - inset * 2), wYear.h - 0.066);
      ctx.clip();
      ctx.globalAlpha *= tl.yearAlpha;
      k15DrawVectorWord(ctx, '2027', startX, topY, hYear, 0.17, 0.36, K15_PALETTE.creamBright, tl.yearDigitOffsetsY);
      ctx.restore();
    }
  }

  /* 6. Windows 4..6: Right Editorial Column — "JOY", "GROWTH", "HOPE" with Split-Mask Highlight Curtain */
  const hopeKeys = [
    { win: K15_WINDOWS.joy, open: tl.winOpen.joy, slideY: tl.hopeSlideY[0], alpha: tl.hopeWordAlpha[0], wipe: tl.highlightWipes[0] },
    { win: K15_WINDOWS.growth, open: tl.winOpen.growth, slideY: tl.hopeSlideY[1], alpha: tl.hopeWordAlpha[1], wipe: tl.highlightWipes[1] },
    { win: K15_WINDOWS.hope, open: tl.winOpen.hope, slideY: tl.hopeSlideY[2], alpha: tl.hopeWordAlpha[2], wipe: tl.highlightWipes[2] }
  ];

  for (let i = 0; i < hopeKeys.length; i++) {
    const item = hopeKeys[i];
    const win = item.win;
    if (!k15DrawWindowFrame(ctx, win, item.open, K15_PALETTE.cardWarm, K15_PALETTE.inkBlack, 0.0020)) continue;

    const visW = win.w * item.open;
    const hWord = 0.068;
    const nudgeX = 0.012 * item.wipe.strength;
    const wordStartX = win.x + 0.106 + nudgeX;
    const wordTopY = win.y + (win.h - hWord) * 0.5 + item.slideY;
    const cyRow = win.y + win.h * 0.5;
    const rowMetaAlpha = k15Clamp01((item.open - 0.50) / 0.45);

    const curtainX0 = win.x + win.w * item.wipe.left;
    const curtainX1 = win.x + win.w * item.wipe.right;
    const hasWipe = curtainX1 - curtainX0 > 0.002;

    /* Pass A: Default Editorial Beige Ink State clipped to open window */
    ctx.save();
    ctx.beginPath();
    ctx.rect(win.x, win.y, visW, win.h);
    ctx.clip();

    if (rowMetaAlpha > 0.01) {
      ctx.save();
      ctx.globalAlpha *= rowMetaAlpha;
      k15DrawEditorialText(ctx, win.idxStr, win.x + 0.036, cyRow, 0.021, '700', 'Georgia, "Times New Roman", serif', K15_PALETTE.forestMid, 'left', 'middle');

      ctx.strokeStyle = K15_PALETTE.gridRule;
      ctx.lineWidth = 0.0014;
      ctx.beginPath();
      ctx.moveTo(win.x + 0.082, win.y + 0.026);
      ctx.lineTo(win.x + 0.082, win.y + win.h - 0.026);
      ctx.stroke();

      k15DrawEditorialText(ctx, win.sub, win.x + win.w - 0.030, cyRow, 0.0145, '700', '"Segoe UI", "Helvetica Neue", Arial, sans-serif', K15_PALETTE.inkMuted, 'right', 'middle');
      ctx.restore();
    }

    if (item.alpha > 0.005) {
      ctx.save();
      ctx.globalAlpha *= item.alpha;
      k15DrawVectorWord(ctx, win.word, wordStartX, wordTopY, hWord, 0.16, 0.36, K15_PALETTE.inkBlack, null);
      ctx.restore();
    }
    ctx.restore();

    /* Pass B: Crisp Split-Wipe Highlight Curtain Clipped Strictly Inside Both Open Window & Wipe Span */
    if (hasWipe) {
      const cL = Math.max(win.x, curtainX0);
      const cR = Math.min(win.x + visW, curtainX1);
      if (cR - cL > 0.001) {
        ctx.save();
        ctx.beginPath();
        ctx.rect(cL, win.y, cR - cL, win.h);
        ctx.clip();

        ctx.fillStyle = win.accentBg;
        ctx.fillRect(win.x, win.y, win.w, win.h);

        k15DrawEditorialText(ctx, win.idxStr, win.x + 0.036, cyRow, 0.021, '700', 'Georgia, "Times New Roman", serif', K15_PALETTE.sandGold, 'left', 'middle');

        ctx.strokeStyle = 'rgba(212, 194, 160, 0.35)';
        ctx.lineWidth = 0.0014;
        ctx.beginPath();
        ctx.moveTo(win.x + 0.082, win.y + 0.026);
        ctx.lineTo(win.x + 0.082, win.y + win.h - 0.026);
        ctx.stroke();

        if (item.alpha > 0.005) {
          ctx.save();
          ctx.globalAlpha *= item.alpha;
          k15DrawVectorWord(ctx, win.word, wordStartX, wordTopY, hWord, 0.16, 0.36, K15_PALETTE.creamBright, null);
          ctx.restore();
        }

        /* Crisp highlighted marker dot + descriptor on right */
        k15DrawEditorialText(ctx, 'FEATURED  •  ' + win.sub, win.x + win.w - 0.030, cyRow, 0.0145, '700', '"Segoe UI", "Helvetica Neue", Arial, sans-serif', K15_PALETTE.sandGold, 'right', 'middle');
        ctx.restore();
      }
    }
  }

  /* 7. Window 7: Bottom Left Obsidian Plate — "HAPPY NEW YEAR" */
  const wBanner = K15_WINDOWS.banner;
  if (k15DrawWindowFrame(ctx, wBanner, tl.winOpen.banner, K15_PALETTE.inkBlack, K15_PALETTE.inkBlack, 0.0020)) {
    ctx.save();
    ctx.beginPath();
    ctx.rect(wBanner.x, wBanner.y, wBanner.w * tl.winOpen.banner, wBanner.h);
    ctx.clip();

    if (tl.bannerAlpha > 0.005) {
      const hBan = 0.062;
      const wBan = k15MeasureTextWidth('HAPPY NEW YEAR', hBan, 0.16, 0.42);
      const bx = wBanner.x + (wBanner.w - wBan) * 0.5;
      const by = wBanner.y + (wBanner.h - hBan) * 0.5 + tl.wordSlideY.banner;

      ctx.save();
      ctx.globalAlpha *= tl.bannerAlpha;
      k15DrawVectorWord(ctx, 'HAPPY NEW YEAR', bx, by, hBan, 0.16, 0.42, K15_PALETTE.creamBright, null);
      ctx.restore();
    }
    ctx.restore();
  }

  /* 8. Window 8: Bottom Right Editorial Status & Chapter Tracker */
  const wStatus = K15_WINDOWS.status;
  if (k15DrawWindowFrame(ctx, wStatus, tl.winOpen.status, K15_PALETTE.cardSand, K15_PALETTE.inkBlack, 0.0020)) {
    const statusAlpha = k15Clamp01((tl.winOpen.status - 0.50) / 0.45);
    if (statusAlpha > 0.01) {
      ctx.save();
      ctx.beginPath();
      ctx.rect(wStatus.x, wStatus.y, wStatus.w * tl.winOpen.status, wStatus.h);
      ctx.clip();
      ctx.globalAlpha *= statusAlpha;

      const sy = wStatus.y + wStatus.h * 0.5 + tl.wordSlideY.status;
      let statusTitle = 'YEAR  •  MMXXVII';
      if (tl.activeKeywordIdx >= 0) {
        const kItem = hopeKeys[tl.activeKeywordIdx].win;
        statusTitle = kItem.idxStr + '  /  ' + kItem.word;
      } else if (tl.safeScene === 0) {
        statusTitle = 'GRID  •  INIT';
      } else if (tl.safeScene === 3) {
        statusTitle = 'FOLIO  •  CLOSE';
      }

      k15DrawEditorialText(ctx, statusTitle, wStatus.x + wStatus.w * 0.5, sy - 0.016, 0.020, '700', 'Georgia, "Times New Roman", serif', K15_PALETTE.forestDeep, 'center', 'middle');

      /* Clean 4-chapter indicator squares centered strictly beneath statusTitle */
      const pipStep = 0.036;
      const pipW = 0.022;
      const pipH = 0.0065;
      const pipStart = wStatus.x + wStatus.w * 0.5 - (3 * pipStep + pipW) * 0.5;
      for (let s = 0; s < 4; s++) {
        const px = pipStart + s * pipStep;
        const isCur = s === tl.safeScene;
        ctx.fillStyle = isCur ? K15_PALETTE.forestDeep : 'rgba(17, 21, 19, 0.25)';
        ctx.fillRect(px, sy + 0.020, pipW, pipH);
      }

      ctx.restore();
    }
  }

  ctx.restore();
}

/* ==========================================================================
   KONSEP 16 — MIDNIGHT CLOCK RINGS (HAPPY NEW YEAR 2027)
   Theme: Happy New Year 2027 | Duration: 20s | Scenes: 4 | Aspect Ratio: 16:9
   Resolution: FHD / 2K / 4K (3840x2160) | Recommended Export Bitrate: 100 Mbps
   Style: Concentric Watchmaker Circular Text Rings, Precision Dial Ticks,
          12:00 Midnight Hand Sweep, Shockwave Rings & Center "2027"
   Pure Canvas 2D API — Zero Background Glow, Zero Overlaps, Seamless Loop
   ========================================================================== */

const EXPORT_CONFIG = {
  width: 3840,
  height: 2160,
  aspectRatio: '16:9',
  fps: 60,
  duration: 20,
  bitrateMbps: 100,
  minBitrateMbps: 100,
  videoBitsPerSecond: 100000000
};

const K16_PALETTE = {
  bgTop: '#070A1C',
  bgMid: '#0D1333',
  bgBot: '#161F4B',
  dialOuter: '#10173B',
  dialTrack: '#141D48',
  dialHub: '#0A0F28',
  copperBright: '#FFE4D4',
  roseGold: '#E6A388',
  copperMid: '#C77D63',
  copperDeep: '#8D4F3C',
  indigoTick: '#4C5899',
  indigoMuted: '#7E8AC4',
  frameLine: 'rgba(230, 163, 136, 0.24)'
};

const K16_TAU = Math.PI * 2;

function k16Clamp01(v) {
  return v < 0 ? 0 : (v > 1 ? 1 : v);
}

function k16Lerp(a, b, t) {
  return a + (b - a) * t;
}

function k16SubRange(t, a, b) {
  return k16Clamp01((t - a) / (b - a));
}

function k16EaseOutCubic(t) {
  const u = 1 - k16Clamp01(t);
  return 1 - u * u * u;
}

function k16EaseInCubic(t) {
  const u = k16Clamp01(t);
  return u * u * u;
}

function k16EaseInOutCubic(t) {
  const u = k16Clamp01(t);
  return u < 0.5 ? 4 * u * u * u : 1 - Math.pow(-2 * u + 2, 3) / 2;
}

function k16EaseOutQuart(t) {
  const u = 1 - k16Clamp01(t);
  return 1 - u * u * u * u;
}

function k16SampleCubic(p0, c1, c2, p1, steps) {
  const pts = [];
  for (let i = 1; i <= steps; i++) {
    const t = i / steps;
    const mt = 1 - t;
    const x = mt * mt * mt * p0[0] + 3 * mt * mt * t * c1[0] + 3 * mt * t * t * c2[0] + t * t * t * p1[0];
    const y = mt * mt * mt * p0[1] + 3 * mt * mt * t * c1[1] + 3 * mt * t * t * c2[1] + t * t * t * p1[1];
    pts.push([x, y]);
  }
  return pts;
}

function k16BuildSuperEllipseRing(cx, cy, rx, ry, power, steps) {
  const pts = [];
  for (let i = 0; i < steps; i++) {
    const a = (i / steps) * K16_TAU;
    const ca = Math.cos(a);
    const sa = Math.sin(a);
    pts.push([
      cx + Math.sign(ca) * Math.pow(Math.abs(ca), 2 / power) * rx,
      cy + Math.sign(sa) * Math.pow(Math.abs(sa), 2 / power) * ry
    ]);
  }
  return pts;
}

function k16DedupRing(pts) {
  const out = [];
  for (let i = 0; i < pts.length; i++) {
    const p = pts[i];
    if (out.length === 0) {
      out.push(p);
    } else {
      const prev = out[out.length - 1];
      if (Math.hypot(p[0] - prev[0], p[1] - prev[1]) > 1e-6) {
        out.push(p);
      }
    }
  }
  if (out.length > 2) {
    const first = out[0];
    const last = out[out.length - 1];
    if (Math.hypot(last[0] - first[0], last[1] - first[1]) <= 1e-6) {
      out.pop();
    }
  }
  return out;
}

/* Crisp Non-Self-Intersecting Horological Glyphs:
   A, B, C, D, E, G, H, I, L, M, N, O, P, R, S, T, U, V, W, Y, 0, 2, 7 */
const K16_GLYPHS = (function () {
  const make = (w, rawRings) => ({ w, rings: rawRings.map(k16DedupRing) });

  const gA = make(0.68, [
    [[0.245, 0], [0.435, 0], [0.68, 1], [0.495, 1], [0.44, 0.77], [0.24, 0.77], [0.185, 1], [0, 1]],
    [[0.34, 0.22], [0.265, 0.59], [0.415, 0.59]]
  ]);

  const gB = make(0.64, [
    [
      [0, 0], [0.36, 0],
      ...k16SampleCubic([0.36, 0], [0.54, 0], [0.60, 0.09], [0.60, 0.24], 14),
      ...k16SampleCubic([0.60, 0.24], [0.60, 0.37], [0.54, 0.45], [0.45, 0.475], 12),
      ...k16SampleCubic([0.45, 0.475], [0.57, 0.505], [0.63, 0.60], [0.63, 0.74], 14),
      ...k16SampleCubic([0.63, 0.74], [0.63, 0.90], [0.55, 1.00], [0.37, 1.00], 14),
      [0, 1.00]
    ],
    [
      [0.18, 0.16], [0.34, 0.16],
      ...k16SampleCubic([0.34, 0.16], [0.41, 0.16], [0.43, 0.195], [0.43, 0.26], 10),
      ...k16SampleCubic([0.43, 0.26], [0.43, 0.345], [0.41, 0.39], [0.34, 0.39], 10),
      [0.18, 0.39]
    ],
    [
      [0.18, 0.56], [0.35, 0.56],
      ...k16SampleCubic([0.35, 0.56], [0.43, 0.56], [0.46, 0.61], [0.46, 0.70], 10),
      ...k16SampleCubic([0.46, 0.70], [0.46, 0.79], [0.43, 0.84], [0.35, 0.84], 10),
      [0.18, 0.84]
