/* Build Exact 360-Degree Periodic Circular Text Layouts (Tight Word Kerning + Uniform Word-Space Distribution) */
function k16BuildRingItems(radius, capH, phrase, repeats, color) {
  const charGap = capH * 0.22;
  const bulletW = capH * 0.26;
  const circum = K16_TAU * radius;

  let fixedArc = 0;
  let spaceCount = 0;
  const tokens = [];

  for (let rep = 0; rep < repeats; rep++) {
    for (let i = 0; i < phrase.length; i++) {
      const ch = phrase[i];
      if (ch === ' ') {
        tokens.push({ kind: 'space', w: 0, addGap: 0 });
        spaceCount++;
      } else {
        const w = ch === '*' ? bulletW : K16_GLYPHS[ch].w * capH;
        const nextIdx = (i + 1) % phrase.length;
        const nextCh = phrase[nextIdx];
        const nextIsChar = nextCh !== ' ';
        const addGap = nextIsChar ? charGap : 0;
        tokens.push({ kind: ch === '*' ? 'dot' : 'glyph', ch, w, addGap });
        fixedArc += w + addGap;
      }
    }
  }

  const spaceW = (circum - fixedArc) / spaceCount;
  const items = [];
  let cursorArc = 0;
  for (let i = 0; i < tokens.length; i++) {
    const tk = tokens[i];
    if (tk.kind === 'space') {
      cursorArc += spaceW;
      continue;
    }
    const midArc = cursorArc + tk.w * 0.5;
    items.push({
      kind: tk.kind,
      ch: tk.ch,
      w: tk.w,
      theta0: midArc / radius
    });
    cursorArc += tk.w + tk.addGap;
  }

  return {
    radius,
    capH,
    minR: radius - capH * 0.5,
    maxR: radius + capH * 0.5,
    color,
    repeats,
    items
  };
}

