function k16DrawCenteredGlyph(ctx, ch, h, fillStyle) {
  const g = K16_GLYPHS[ch];
  const x0 = -g.w * h * 0.5;
  const y0 = -h * 0.5;
  ctx.beginPath();
  for (let r = 0; r < g.rings.length; r++) {
    const ring = g.rings[r];
    ctx.moveTo(x0 + ring[0][0] * h, y0 + ring[0][1] * h);
    for (let k = 1; k < ring.length; k++) {
      ctx.lineTo(x0 + ring[k][0] * h, y0 + ring[k][1] * h);
    }
    ctx.closePath();
  }
  ctx.fillStyle = fillStyle;
  ctx.fill('evenodd');
}

function k16DrawHero2027(ctx, scaleVal, alphaVal) {
  if (alphaVal <= 0.005) return;
  const digH = 0.072 * scaleVal;
  const gap = digH * 0.16;
  const chars = ['2', '0', '2', '7'];
  let totalW = 0;
  for (let i = 0; i < 4; i++) {
    totalW += K16_GLYPHS[chars[i]].w * digH;
    if (i < 3) totalW += gap;
  }

  let cursor = -totalW * 0.5;
  ctx.save();
  ctx.globalAlpha *= alphaVal;

  const grad = ctx.createLinearGradient(0, -digH * 0.5, 0, digH * 0.5);
  grad.addColorStop(0.0, K16_PALETTE.copperBright);
  grad.addColorStop(0.5, K16_PALETTE.roseGold);
  grad.addColorStop(1.0, K16_PALETTE.copperMid);

  for (let i = 0; i < 4; i++) {
    const ch = chars[i];
    const dw = K16_GLYPHS[ch].w * digH;
    ctx.save();
    ctx.translate(cursor + dw * 0.5, 0);
    k16DrawCenteredGlyph(ctx, ch, digH, grad);
    ctx.restore();
    cursor += dw + gap;
  }

  ctx.restore();
}

function k16DrawEditorialText(ctx, text, x, y, sizeU, weight, family, color, align, baseline) {
  ctx.save();
  ctx.translate(x, y);
  ctx.scale(0.001, 0.001);
  ctx.font = weight + ' ' + (sizeU * 1000).toFixed(1) + 'px ' + family;
  ctx.fillStyle = color;
  ctx.textAlign = align || 'left';
  ctx.textBaseline = baseline || 'middle';
  ctx.fillText(text, 0, 0);
  ctx.restore();
}

function k16DrawClockHand(ctx, angleFrom12, length, baseW, tailLen, color, cutColor) {
  if (length <= 0.004) return;
  ctx.save();
  ctx.rotate(angleFrom12);

  /* Crisp tapered watchmaker dauphine/lancet needle pointing toward -Y (12 o'clock at 0 rad) */
  ctx.beginPath();
  ctx.moveTo(0, -length);
  ctx.lineTo(baseW, -length * 0.16);
  ctx.lineTo(baseW * 0.65, tailLen);
  ctx.lineTo(-baseW * 0.65, tailLen);
  ctx.lineTo(-baseW, -length * 0.16);
  ctx.closePath();
  ctx.fillStyle = color;
  ctx.fill();

  /* Precision recessed central spine slot strictly inset inside needle */
  if (length > 0.045) {
    ctx.beginPath();
    ctx.moveTo(0, -length * 0.80);
    ctx.lineTo(baseW * 0.34, -length * 0.22);
    ctx.lineTo(-baseW * 0.34, -length * 0.22);
    ctx.closePath();
    ctx.fillStyle = cutColor;
    ctx.fill();
  }

  ctx.restore();
}

/* Compute exact continuous radial & angular horology state (shared by render + invariant validator) */
function k16EvaluateDialState(loopT) {
  const duration = 20;
  const sceneCount = 4;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const safeScene = ((currentScene % sceneCount) + sceneCount) % sceneCount;
  const p = sceneProgress < 0 ? sceneProgress + 1 : sceneProgress;

  /* Smooth continuous angular drift across [0..20s], scaled by 2-turn periodic modulation */
  const uGlobal = loopT / duration;
  const rot1 = uGlobal * (Math.PI * 1.0) + 0.12 * Math.sin(uGlobal * K16_TAU);
  const rot2 = -uGlobal * (Math.PI * 1.0) - 0.14 * Math.sin(uGlobal * K16_TAU * 2);
  const rot3 = uGlobal * (Math.PI * 2.0) + 0.10 * Math.sin(uGlobal * K16_TAU);

  let ringScale = [1, 1, 1];
  let ringAlpha = [1, 1, 1];
  let ringSweep = [1, 1, 1];
  let sepAlpha = 1;
  let tickReveal = 1;
  let handsAlpha = 0;
  let handsRetract = 1; /* 1 = full length, 0 = retracted cleanly at 12:00 strike */
  let minuteAng = -0.34;
  let hourAng = -0.045;
  let shockWaves = [];
  let heroAlpha = 0;
  let heroScale = 1;
  let chronoDialFraction = uGlobal;

  if (safeScene === 0) {
    /* SCENE 0 (0 - 5s): Concentric circular text rings sweep & rotate gracefully into view */
    for (let i = 0; i < 3; i++) {
      const ui = k16EaseOutCubic(k16SubRange(p, i * 0.13, 0.62 + i * 0.13));
      ringScale[i] = k16Lerp(0.93, 1.0, ui);
      ringAlpha[i] = ui;
      ringSweep[i] = ui;
    }
    sepAlpha = k16EaseOutCubic(k16SubRange(p, 0.05, 0.72));
    tickReveal = 0;
    const hIn = k16EaseOutCubic(k16SubRange(p, 0.56, 0.96));
    handsAlpha = hIn;
    handsRetract = hIn;
    minuteAng = k16Lerp(-0.78, -0.52, hIn);
    hourAng = k16Lerp(-0.12, -0.072, hIn);
    heroAlpha = 0;
  } else if (safeScene === 1) {
    /* SCENE 1 (5 - 10s): 60 minute ticks & 12 hour baton markers draw sequentially around perimeter */
    tickReveal = k16EaseInOutCubic(k16SubRange(p, 0.04, 0.88));
    const adv = k16EaseInOutCubic(p);
    handsAlpha = 1;
    handsRetract = 1;
    minuteAng = k16Lerp(-0.52, -0.18, adv);
    hourAng = k16Lerp(-0.072, -0.025, adv);
    heroAlpha = 0;
  } else if (safeScene === 2) {
    /* SCENE 2 (10 - 15s): Hands sweep to exact 12:00 -> Shockwaves -> Center hub clears for "2027" */
    const reach12 = k16EaseOutQuart(k16SubRange(p, 0.00, 0.38));
    minuteAng = k16Lerp(-0.18, 0.0, reach12);
    hourAng = k16Lerp(-0.025, 0.0, reach12);

    const retractP = k16EaseInOutCubic(k16SubRange(p, 0.40, 0.56));
    handsRetract = 1 - retractP;
    handsAlpha = 1 - k16SubRange(p, 0.46, 0.56);

    /* Crisp non-overlapping expanding shockwave rings:
       - Outer bezel halo shockwaves strictly outside dial edge [0.396 .. 0.431]
       - Inner chamber shockwave strictly inside clear center chamber [0.020 .. 0.168] */
    const outerSw = [
      [0.38, 0.76],
      [0.46, 0.86]
    ];
    for (let s = 0; s < outerSw.length; s++) {
      const sp = k16SubRange(p, outerSw[s][0], outerSw[s][1]);
      if (sp > 0.002 && sp < 0.998) {
        const eased = k16EaseOutCubic(sp);
        shockWaves.push({
          zone: 'outer',
          r: k16Lerp(0.396, 0.431, eased),
          alpha: (1 - eased) * 0.92,
          lw: k16Lerp(0.0040, 0.0012, eased)
        });
      }
    }
    const innerSw = k16SubRange(p, 0.38, 0.56);
    if (innerSw > 0.002 && innerSw < 0.998) {
      const easedIn = k16EaseOutCubic(innerSw);
      shockWaves.push({
        zone: 'inner',
        r: k16Lerp(0.020, 0.168, easedIn),
        alpha: (1 - easedIn) * 0.85,
        lw: k16Lerp(0.0032, 0.0012, easedIn)
      });
    }

    const hAppear = k16EaseOutCubic(k16SubRange(p, 0.56, 0.88));
    heroAlpha = hAppear;
    heroScale = k16Lerp(0.84, 1.0, hAppear);
  } else {
    /* SCENE 3 (15 - 20s): "2027" pulses proportionally twice -> Rings & markers sweep cleanly back to t=0 */
    const pulseEnv = Math.sin(Math.PI * k16SubRange(p, 0.00, 0.46));
    const doublePulse = Math.sin(k16SubRange(p, 0.00, 0.46) * K16_TAU * 2) * pulseEnv;
    const hOut = k16EaseInCubic(k16SubRange(p, 0.48, 0.78));
    heroAlpha = 1 - hOut;
    heroScale = (1.0 + 0.055 * doublePulse) * k16Lerp(1.0, 0.86, hOut);

    tickReveal = 1 - k16EaseInOutCubic(k16SubRange(p, 0.52, 0.88));
    sepAlpha = 1 - k16EaseInCubic(k16SubRange(p, 0.60, 0.96));

    for (let i = 0; i < 3; i++) {
      const outi = k16EaseInCubic(k16SubRange(p, 0.56 + i * 0.06, 0.96));
      ringScale[i] = k16Lerp(1.0, 0.93, outi);
      ringAlpha[i] = 1 - outi;
      ringSweep[i] = 1 - outi;
    }
  }

  return {
    safeScene,
    p,
    rot: [rot1, rot2, rot3],
    ringScale,
    ringAlpha,
    ringSweep,
    sepAlpha,
    tickReveal,
    handsAlpha,
    handsRetract,
    minuteAng,
    hourAng,
    shockWaves,
    heroAlpha,
    heroScale,
    chronoDialFraction
  };
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const safeLoopT = loopT < 0 ? loopT + duration : loopT;
  const st = k16EvaluateDialState(safeLoopT);

  const U = Math.min(height, width / (16 / 9));
  const halfW = (width / U) * 0.5;

  ctx.save();
  ctx.shadowBlur = 0;

  /* 1. Deep Midnight Indigo Matte Linear Backdrop (Zero Background Glow) */
  const bgGrad = ctx.createLinearGradient(0, 0, width * 0.3, height);
  bgGrad.addColorStop(0.0, K16_PALETTE.bgTop);
  bgGrad.addColorStop(0.52, K16_PALETTE.bgMid);
  bgGrad.addColorStop(1.0, K16_PALETTE.bgBot);
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);

  ctx.translate(width * 0.5, height * 0.5);
  ctx.scale(U, U);

  const fw = Math.min(halfW - 0.038, 0.815);

  /* 2. Grounded Matte Watchmaker Dial Plate & Static Outer Bezel (Zero Overlap) */
  const rOuter = 0.396;
  ctx.beginPath();
  ctx.arc(0, 0, rOuter, 0, K16_TAU);
  ctx.fillStyle = K16_PALETTE.dialOuter;
  ctx.fill();
  ctx.lineWidth = 0.0024;
  ctx.strokeStyle = K16_PALETTE.copperDeep;
  ctx.stroke();

  /* Recessed Center Chamber Circle (r = 0.174) strictly framing Hands & "2027" */
  ctx.beginPath();
  ctx.arc(0, 0, 0.174, 0, K16_TAU);
  ctx.fillStyle = K16_PALETTE.dialHub;
  ctx.fill();
  ctx.lineWidth = 0.0022;
  ctx.strokeStyle = K16_PALETTE.copperMid;
  ctx.stroke();

  /* 3. Concentric Separator Bezels (animated sweep reveal) */
  if (st.sepAlpha > 0.004) {
    const sepRadii = [0.345, 0.294, 0.246, 0.184];
    ctx.save();
    ctx.globalAlpha *= st.sepAlpha * 0.72;
    ctx.strokeStyle = K16_PALETTE.copperDeep;
    ctx.lineWidth = 0.0014;
    for (let i = 0; i < sepRadii.length; i++) {
      ctx.beginPath();
      ctx.arc(0, 0, sepRadii[i], -Math.PI * 0.5, -Math.PI * 0.5 + K16_TAU * st.sepAlpha);
      ctx.stroke();
    }
    ctx.restore();
  }

  /* 4. Tick Track (r = 0.302 .. 0.338): 60 Minute Ticks + 12 Tapered Hour Batons Drawn Clockwise */
  if (st.tickReveal > 0.004) {
    /* 60 precision minute ticks */
    for (let m = 0; m < 60; m++) {
      if (m % 5 === 0) continue;
      const frac = m / 60;
      const mp = k16EaseOutCubic(k16SubRange(st.tickReveal, frac * 0.72, frac * 0.72 + 0.18));
      if (mp <= 0.01) continue;
      const ang = (m / 60) * K16_TAU - Math.PI * 0.5;
      const ca = Math.cos(ang), sa = Math.sin(ang);
      const rEnd = 0.338;
      const rStart = k16Lerp(rEnd, 0.328, mp);
      ctx.beginPath();
      ctx.moveTo(ca * rStart, sa * rStart);
      ctx.lineTo(ca * rEnd, sa * rEnd);
      ctx.lineWidth = 0.0016;
      ctx.strokeStyle = K16_PALETTE.indigoTick;
      ctx.stroke();
    }

    /* 12 Bold Watchmaker Hour Baton Markers */
    for (let h = 0; h < 12; h++) {
      const frac = h / 12;
      const hp = k16EaseOutCubic(k16SubRange(st.tickReveal, frac * 0.70, frac * 0.70 + 0.24));
      if (hp <= 0.01) continue;
      const ang = (h / 12) * K16_TAU; /* relative to 12 o'clock (-Y axis) */
      const isQuarter = (h % 3) === 0;
      const rTop = -0.338;
      const len = (isQuarter ? 0.036 : 0.026) * hp;

      ctx.save();
      ctx.rotate(ang);
      ctx.fillStyle = h === 0 ? K16_PALETTE.copperBright : (isQuarter ? K16_PALETTE.roseGold : K16_PALETTE.copperMid);
      if (h === 0) {
        /* Distinct double baton at 12:00 */
        ctx.fillRect(-0.0070, rTop, 0.0050, len);
        ctx.fillRect(0.0020, rTop, 0.0050, len);
      } else {
        const w = isQuarter ? 0.0066 : 0.0044;
        ctx.fillRect(-w * 0.5, rTop, w, len);
      }
      ctx.restore();
    }
  }

  /* 5. Three Concentric Counter-Rotating Circular Text Rings */
  for (let ri = 0; ri < K16_RING_SPECS.length; ri++) {
    const spec = K16_RING_SPECS[ri];
    const alpha = st.ringAlpha[ri];
    if (alpha <= 0.005) continue;

    const rScaled = spec.radius * st.ringScale[ri];
    const hGlyph = spec.capH * st.ringScale[ri];
    const maxAngleSpan = st.ringSweep[ri] * (K16_TAU + 0.28);
    const rotAngle = st.rot[ri];

    ctx.save();
    ctx.globalAlpha *= alpha;
    for (let k = 0; k < spec.items.length; k++) {
      const item = spec.items[k];
      /* Sweep reveal normalized along [0..2PI] */
      const sweepPos = ((item.theta0 % K16_TAU) + K16_TAU) % K16_TAU;
      const itemFade = k16Clamp01((maxAngleSpan - sweepPos) / 0.25);
      if (itemFade <= 0.01) continue;

      const theta = item.theta0 + rotAngle;
      ctx.save();
      ctx.globalAlpha *= itemFade;
      ctx.rotate(theta);
      ctx.translate(0, -rScaled);
      if (item.kind === 'dot') {
        ctx.beginPath();
        ctx.arc(0, 0, hGlyph * 0.14, 0, K16_TAU);
        ctx.fillStyle = K16_PALETTE.copperBright;
        ctx.fill();
      } else {
        k16DrawCenteredGlyph(ctx, item.ch, hGlyph, spec.color);
      }
      ctx.restore();
    }
    ctx.restore();
  }

  /* 6. Midnight Strike Shockwaves (Crisp Non-Glow Geometric Ripples, bounded in [0.178 .. 0.422]) */
  for (let s = 0; s < st.shockWaves.length; s++) {
    const sw = st.shockWaves[s];
    ctx.save();
    ctx.globalAlpha *= sw.alpha;
    ctx.beginPath();
    ctx.arc(0, 0, sw.r, 0, K16_TAU);
    ctx.lineWidth = sw.lw;
    ctx.strokeStyle = s === 0 ? K16_PALETTE.copperBright : K16_PALETTE.roseGold;
    ctx.stroke();
    ctx.restore();
  }

  /* 7. Center Chamber Contents: Clock Hands (Pre-Midnight) -> Clear Hub -> "2027" Centerpiece */
  if (st.handsAlpha > 0.005 && st.handsRetract > 0.01) {
    ctx.save();
    ctx.globalAlpha *= st.handsAlpha;

    /* Subtle inner watchmaker rosette ring */
    ctx.beginPath();
    ctx.arc(0, 0, 0.068 * st.handsRetract, 0, K16_TAU);
    ctx.lineWidth = 0.0014;
    ctx.strokeStyle = 'rgba(230, 163, 136, 0.30)';
    ctx.stroke();

    k16DrawClockHand(ctx, st.hourAng, 0.104 * st.handsRetract, 0.0095, 0.020 * st.handsRetract, K16_PALETTE.copperMid, K16_PALETTE.dialHub);
    k16DrawClockHand(ctx, st.minuteAng, 0.148 * st.handsRetract, 0.0068, 0.026 * st.handsRetract, K16_PALETTE.copperBright, K16_PALETTE.dialHub);

    /* Pivot center cap */
    ctx.beginPath();
    ctx.arc(0, 0, 0.013 * st.handsRetract, 0, K16_TAU);
    ctx.fillStyle = K16_PALETTE.roseGold;
    ctx.fill();
    ctx.beginPath();
    ctx.arc(0, 0, 0.0055 * st.handsRetract, 0, K16_TAU);
    ctx.fillStyle = K16_PALETTE.dialHub;
    ctx.fill();

    ctx.restore();
  }

  if (st.heroAlpha > 0.005) {
    ctx.save();
    ctx.globalAlpha *= st.heroAlpha;
    k16DrawHero2027(ctx, st.heroScale, 1);

    /* Delicate calibrated flanking tags strictly inside center hub r <= 0.155 */
    k16DrawEditorialText(ctx, 'MIDNIGHT  •  12:00', 0, -0.068 * st.heroScale, 0.0115 * st.heroScale, '700', '"Segoe UI", "Helvetica Neue", Arial, sans-serif', K16_PALETTE.roseGold, 'center', 'middle');
    k16DrawEditorialText(ctx, 'HAPPY NEW YEAR', 0, 0.068 * st.heroScale, 0.0115 * st.heroScale, '700', '"Segoe UI", "Helvetica Neue", Arial, sans-serif', K16_PALETTE.copperBright, 'center', 'middle');

    const lineW = 0.064 * st.heroScale;
    ctx.fillStyle = K16_PALETTE.copperMid;
    ctx.fillRect(-lineW, -0.050 * st.heroScale, lineW * 2, 0.0014);
    ctx.fillRect(-lineW, 0.050 * st.heroScale, lineW * 2, 0.0014);
    ctx.restore();
  }

  /* 8. Architectural Watchmaker Side Columns (Strictly Separated >= 0.065 outside Dial Outer Radius 0.422) */
  const flankEdgeIn = 0.488;
  const flankEdgeOut = Math.min(fw - 0.036, 0.772);
  const flankCx = (flankEdgeIn + flankEdgeOut) * 0.5;

  /* Left Flank: Calibrated Vertical Chronometer Rail + Phase Markers */
  ctx.save();
  ctx.strokeStyle = 'rgba(230, 163, 136, 0.25)';
  ctx.lineWidth = 0.0014;
  ctx.beginPath();
  ctx.moveTo(-flankEdgeIn, -0.26);
  ctx.lineTo(-flankEdgeIn, 0.26);
  ctx.moveTo(flankEdgeIn, -0.26);
  ctx.lineTo(flankEdgeIn, 0.26);
  ctx.stroke();

  const scaleLen = 0.20;
  for (let i = -8; i <= 8; i++) {
    const ty = i * (scaleLen / 8);
    const isMajor = (Math.abs(i) % 4) === 0;
    const tw = isMajor ? 0.022 : 0.010;
    ctx.strokeStyle = isMajor ? K16_PALETTE.roseGold : K16_PALETTE.indigoTick;
    ctx.lineWidth = isMajor ? 0.0020 : 0.0012;
    ctx.beginPath();
    ctx.moveTo(-flankEdgeIn - 0.014 - tw, ty);
    ctx.lineTo(-flankEdgeIn - 0.014, ty);
    ctx.moveTo(flankEdgeIn + 0.014, ty);
    ctx.lineTo(flankEdgeIn + 0.014 + tw, ty);
    ctx.stroke();
  }

  /* Animated symmetrical traveling reticle diamonds on vertical calibration tracks (exact periodic sine) */
  const reticleY = Math.sin(st.chronoDialFraction * K16_TAU) * 0.15;
  ctx.fillStyle = K16_PALETTE.copperBright;
  ctx.fillRect(-flankEdgeIn - 0.006, reticleY - 0.006, 0.012, 0.012);
  ctx.fillRect(flankEdgeIn - 0.006, -reticleY - 0.006, 0.012, 0.012);

  /* Left Flank Editorial Label + Chapter Gauge */
  k16DrawEditorialText(ctx, 'CHRONO // MMXXVII', -flankCx, -0.115, 0.0135, '700', '"Segoe UI", "Helvetica Neue", Arial, sans-serif', K16_PALETTE.roseGold, 'center', 'middle');
  k16DrawEditorialText(ctx, 'SYNCHRONIZED DIAL', -flankCx, 0.115, 0.0125, '600', 'Georgia, "Times New Roman", serif', K16_PALETTE.indigoMuted, 'center', 'middle');

  const smallGaugeR = 0.056;
  ctx.beginPath();
  ctx.arc(-flankCx, 0, smallGaugeR, 0, K16_TAU);
  ctx.lineWidth = 0.0016;
  ctx.strokeStyle = 'rgba(230, 163, 136, 0.28)';
  ctx.stroke();

  const arcLeftAngle = -Math.PI * 0.5 + st.chronoDialFraction * K16_TAU;
  ctx.beginPath();
  ctx.arc(-flankCx, 0, smallGaugeR, arcLeftAngle, arcLeftAngle + Math.PI * 0.65);
  ctx.lineWidth = 0.0030;
  ctx.strokeStyle = K16_PALETTE.roseGold;
  ctx.stroke();

  /* Right Flank: Secondary Escapement Balance Ring + Scene Phase Indicator */
  k16DrawEditorialText(ctx, 'MIDNIGHT  •  00:00', flankCx, -0.115, 0.0135, '700', '"Segoe UI", "Helvetica Neue", Arial, sans-serif', K16_PALETTE.roseGold, 'center', 'middle');
  k16DrawEditorialText(ctx, 'TWELVE O\'CLOCK STRIKE', flankCx, 0.115, 0.0125, '600', 'Georgia, "Times New Roman", serif', K16_PALETTE.indigoMuted, 'center', 'middle');

  ctx.beginPath();
  ctx.arc(flankCx, 0, smallGaugeR, 0, K16_TAU);
  ctx.lineWidth = 0.0016;
  ctx.strokeStyle = 'rgba(230, 163, 136, 0.28)';
  ctx.stroke();

  const arcRightAngle = -Math.PI * 0.5 - st.chronoDialFraction * K16_TAU;
  ctx.beginPath();
  ctx.arc(flankCx, 0, smallGaugeR, arcRightAngle, arcRightAngle + Math.PI * 0.65);
  ctx.lineWidth = 0.0030;
  ctx.strokeStyle = K16_PALETTE.copperBright;
  ctx.stroke();

  /* Right small center diamond marker inside gauge */
  const pipStep = 0.024;
  for (let s = 0; s < 4; s++) {
    const px = flankCx + (s - 1.5) * pipStep;
    ctx.beginPath();
    ctx.arc(px, 0.155, s === st.safeScene ? 0.0052 : 0.0032, 0, K16_TAU);
    ctx.fillStyle = s === st.safeScene ? K16_PALETTE.copperBright : K16_PALETTE.copperDeep;
    ctx.fill();
  }

  ctx.restore();
  ctx.restore();
}

/* ==========================================================================
   KONSEP 14 — SQUASH UNFOLD STACK (NEW YEAR 2027)
   Theme: Happy New Year 2027 | Duration: 20s | Scenes: 4 | Aspect Ratio: 16:9
   Resolution: FHD / 2K / 4K (3840x2160) | Recommended Export Bitrate: 100 Mbps
   Style: Sporty Vertical Word Stack -> Collision-Free Unfold to "NEW YEAR 2027"
   Pure Canvas 2D API — Zero Background Glow, Zero Overlaps, Seamless Loop
   ========================================================================== */

const EXPORT_CONFIG = {
  width: 3840,
  height: 2160,
  aspectRatio: '16:9',
  fps: 60,
  duration: 20,
  bitrateMbps: 100,
  minBitrateMbps: 100,
  videoBitsPerSecond: 100000000
};

const K14_PALETTE = {
  bgDeep: '#1B0938',
  bgRoyal: '#2E1065',
  bgPlum: '#44167D',
  white: '#FFFFFF',
  peachBright: '#FFD6CB',
  peachWarm: '#FF9888',
