  const gW = make(0.90, [[[0, 0], [0.185, 0], [0.275, 0.68], [0.39, 0], [0.51, 0], [0.625, 0.68], [0.715, 0], [0.90, 0], [0.715, 1], [0.54, 1], [0.45, 0.39], [0.36, 1], [0.185, 1]]]);

