  const gA = make(0.70, [[[0.245, 0], [0.455, 0], [0.70, 1], [0.51, 1], [0.455, 0.77], [0.245, 0.77], [0.19, 1], [0, 1]], [[0.35, 0.23], [0.275, 0.59], [0.425, 0.59]]]);
  const gR = make(0.66, [
