    [[0.185, 0.165], [0.34, 0.165], ...k14SampleCubic([0.34, 0.165], [0.43, 0.165], [0.46, 0.20], [0.46, 0.28], 10), ...k14SampleCubic([0.46, 0.28], [0.46, 0.365], [0.43, 0.405], [0.34, 0.405], 10), [0.185, 0.405]]
