    ...k14SampleCubic([0.64, 0.30], [0.64, 0.51], [0.475, 0.65], [0.24, 0.84], 22),
    [0.64, 0.84], [0.64, 1.00], [0.02, 1.00], [0.02, 0.86],
    ...k14SampleCubic([0.02, 0.86], [0.21, 0.63], [0.465, 0.48], [0.465, 0.29], 22),
