    ...k14SampleCubic([0.34, 0.15], [0.25, 0.15], [0.205, 0.20], [0.205, 0.31], 10)
  ]]);

  const d7 = make(0.64, [[
    [0.02, 0.00], [0.62, 0.00], [0.62, 0.155],
    ...k14SampleCubic([0.62, 0.155], [0.485, 0.40], [0.38, 0.70], [0.34, 1.00], 22),
    [0.16, 1.00],
    ...k14SampleCubic([0.16, 1.00], [0.21, 0.70], [0.315, 0.40], [0.435, 0.155], 22),
    [0.145, 0.155], [0.145, 0.23], [0.02, 0.23]
  ]]);

  return { N: gN, E: gE, W: gW, Y: gY, A: gA, R: gR, '0': d0, '2': d2, '7': d7 };
})();

function k14MeasureWord(chars, h, gapRatio) {
  let w = 0;
  const gap = h * gapRatio;
  for (let i = 0; i < chars.length; i++) {
    w += K14_GLYPHS[chars[i]].w * h;
    if (i < chars.length - 1) w += gap;
  }
  return w;
}

/* Precomputed Stack vs Horizontal Positions for All 11 Characters ("NEW" | "YEAR" | "2027") */
const K14_WORD_H = 0.110;
const K14_CHAR_GAP_RATIO = 0.17;
const K14_STACK_SCALE_X = 0.90;
const K14_STACK_SCALE_Y = 1.08;
const K14_WORD_GAP = 0.068;

const K14_CHARS = (function () {
  const words = [
    { text: 'NEW', row: 0, stackY: -0.172, color: K14_PALETTE.white },
    { text: 'YEAR', row: 1, stackY: 0.000, color: K14_PALETTE.peachWarm },
    { text: '2027', row: 2, stackY: 0.172, color: K14_PALETTE.white }
  ];

  const wordWidthsHoriz = words.map(w => k14MeasureWord(w.text, K14_WORD_H, K14_CHAR_GAP_RATIO));
  const totalHorizW = wordWidthsHoriz[0] + wordWidthsHoriz[1] + wordWidthsHoriz[2] + K14_WORD_GAP * 2;
  let horizWordCursor = -totalHorizW * 0.5;

  const list = [];
  let idx = 0;

  for (let wi = 0; wi < words.length; wi++) {
    const w = words[wi];
    const hGap = K14_WORD_H * K14_CHAR_GAP_RATIO;

    /* Vertical stack uses compressed X scale (0.90), centered around x=0 */
    const stackTotalW = wordWidthsHoriz[wi] * K14_STACK_SCALE_X;
    let stackCursor = -stackTotalW * 0.5;
    let horizCursor = horizWordCursor;

    for (let ci = 0; ci < w.text.length; ci++) {
      const ch = w.text[ci];
      const gw = K14_GLYPHS[ch].w * K14_WORD_H;
      const sW = gw * K14_STACK_SCALE_X;

      const stackCx = stackCursor + sW * 0.5;
      const horizCx = horizCursor + gw * 0.5;

      list.push({
        idx,
        wordIdx: wi,
        charIdxInWord: ci,
        ch,
        color: w.color,
        glyphW: gw,
        stackCx,
        stackCy: w.stackY,
        horizCx,
        horizCy: 0.0
      });

      stackCursor += sW + hGap * K14_STACK_SCALE_X;
      horizCursor += gw + hGap;
      idx++;
    }

    horizWordCursor += wordWidthsHoriz[wi] + K14_WORD_GAP;
  }

  return list;
})();

function k14DrawGlyphCentered(ctx, ch, h, fillStyle) {
  const g = K14_GLYPHS[ch];
  const gw = g.w * h;
  const x0 = -gw * 0.5;
  const y0 = -h * 0.5;

  ctx.beginPath();
  for (let r = 0; r < g.rings.length; r++) {
    const ring = g.rings[r];
    ctx.moveTo(x0 + ring[0][0] * h, y0 + ring[0][1] * h);
    for (let k = 1; k < ring.length; k++) {
      ctx.lineTo(x0 + ring[k][0] * h, y0 + ring[k][1] * h);
    }
    ctx.closePath();
  }
  ctx.fillStyle = fillStyle;
  ctx.fill('evenodd');
}

/* Compute exact transform & bounding box of every letter at time loopT (shared by render + collision test) */
function k14EvaluateLetterStates(loopT) {
  const duration = 20;
  const sceneCount = 4;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const safeScene = ((currentScene % sceneCount) + sceneCount) % sceneCount;
  const safeProgress = sceneProgress < 0 ? sceneProgress + 1 : sceneProgress;

  const states = [];
  for (let i = 0; i < K14_CHARS.length; i++) {
    const c = K14_CHARS[i];
    let cx = c.stackCx;
    let cy = c.stackCy;
    let sx = K14_STACK_SCALE_X;
    let sy = K14_STACK_SCALE_Y;

    if (safeScene === 0) {
      /* SCENE 0 (0 - 5s): Vertical Stack Rhythmic Proportional Pulse (Exact loop: 0 at p=0 & p=1) */
      const phase = safeProgress * K14_TAU * 2 - c.wordIdx * 0.55 - c.charIdxInWord * 0.22;
      const env = Math.sin(Math.PI * safeProgress);
      const pulse = Math.sin(phase) * env;
      sx = K14_STACK_SCALE_X * (1 + 0.045 * pulse);
      sy = K14_STACK_SCALE_Y * (1 - 0.042 * pulse);
    } else if (safeScene === 1) {
      /* SCENE 1 (5 - 10s): Strictly Collision-Free Staggered Unfold (Horizontal outer-lead -> Vertical converge) */
      const stgX = (c.wordIdx === 0)
        ? c.charIdxInWord * 0.032
        : (c.wordIdx === 2 ? (3 - c.charIdxInWord) * 0.028 : 0.015);
      const hx = k14EaseOutBackSoft(k14SubRange(safeProgress, 0.05 + stgX, 0.52 + stgX));
      const vy = k14EaseInOutCubic(k14SubRange(safeProgress, 0.44 + stgX * 0.4, 0.88 + stgX * 0.2));

      cx = k14Lerp(c.stackCx, c.horizCx, hx);
      cy = k14Lerp(c.stackCy, c.horizCy, vy);

      const uScale = k14EaseInOutCubic(k14SubRange(safeProgress, 0.10 + stgX, 0.85));
      sx = k14Lerp(K14_STACK_SCALE_X, 1.0, uScale);
      sy = k14Lerp(K14_STACK_SCALE_Y, 1.0, uScale);
    } else if (safeScene === 2) {
      /* SCENE 2 (10 - 15s): Synchronized Horizontal Harmonic Wave with Subtle Area-Preserving Stretch */
      const env = Math.sin(Math.PI * safeProgress);
      const wavePhase = safeProgress * K14_TAU * 2 - i * 0.50;
      const dy = Math.sin(wavePhase) * 0.042 * env;
      const stretch = Math.cos(wavePhase) * 0.040 * env;

      cx = c.horizCx;
      cy = c.horizCy + dy;
      sx = 1.0 - stretch * 0.7;
      sy = 1.0 + stretch;
    } else {
      /* SCENE 3 (15 - 20s): Guaranteed Safe Refold (Vertical separation first -> Horizontal gather to Stack) */
      const stgY = c.charIdxInWord * 0.022;
      const stgX = (c.wordIdx === 0)
        ? (2 - c.charIdxInWord) * 0.028
        : (c.wordIdx === 2 ? c.charIdxInWord * 0.025 : 0.015);
      const vy = k14EaseInOutCubic(k14SubRange(safeProgress, 0.05 + stgY, 0.48 + stgY));
      const hx = k14EaseInOutCubic(k14SubRange(safeProgress, 0.44 + stgX * 0.4, 0.88 + stgX * 0.2));

      cx = k14Lerp(c.horizCx, c.stackCx, hx);
      cy = k14Lerp(c.horizCy, c.stackCy, vy);

      const uScale = k14EaseInOutCubic(k14SubRange(safeProgress, 0.12, 0.88));
      sx = k14Lerp(1.0, K14_STACK_SCALE_X, uScale);
      sy = k14Lerp(1.0, K14_STACK_SCALE_Y, uScale);
    }

    const halfWBox = c.glyphW * sx * 0.5;
    const halfHBox = K14_WORD_H * sy * 0.5;
    states.push({
      ch: c.ch,
      color: c.color,
      cx,
      cy,
      sx,
      sy,
      minX: cx - halfWBox,
      maxX: cx + halfWBox,
      minY: cy - halfHBox,
      maxY: cy + halfHBox
    });
  }

  return { safeScene, safeProgress, states };
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const safeLoopT = loopT < 0 ? loopT + duration : loopT;
  const evalData = k14EvaluateLetterStates(safeLoopT);
  const safeScene = evalData.safeScene;
  const safeProgress = evalData.safeProgress;
  const states = evalData.states;

  const U = Math.min(height, width / (16 / 9));
  const halfW = (width / U) * 0.5;

  ctx.save();
  ctx.shadowBlur = 0;

  /* 1. Royal Purple to Plum-Night Linear Gradient (Zero glow) */
  const bgGrad = ctx.createLinearGradient(0, 0, width, height);
  bgGrad.addColorStop(0.0, K14_PALETTE.bgDeep);
  bgGrad.addColorStop(0.55, K14_PALETTE.bgRoyal);
  bgGrad.addColorStop(1.0, K14_PALETTE.bgPlum);
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);

  ctx.translate(width * 0.5, height * 0.5);
  ctx.scale(U, U);

  /* 2. Morphing Sporty Container Rails — Strictly Sequenced Outside Letter Bounding Boxes */
  let vertAlpha = 1;
  let horizAlpha = 0;
  let railX = 0.245;
  if (safeScene === 0) {
    vertAlpha = 1;
    horizAlpha = 0;
  } else if (safeScene === 1) {
    const vertFadeOut = k14EaseInOutCubic(k14SubRange(safeProgress, 0.00, 0.18));
    vertAlpha = 1 - vertFadeOut;
    railX = k14Lerp(0.245, 0.340, vertFadeOut);
    horizAlpha = k14EaseInOutCubic(k14SubRange(safeProgress, 0.76, 0.95));
  } else if (safeScene === 2) {
    vertAlpha = 0;
    horizAlpha = 1;
  } else {
    const horizFadeOut = k14EaseInOutCubic(k14SubRange(safeProgress, 0.00, 0.18));
    horizAlpha = 1 - horizFadeOut;
    const vertFadeIn = k14EaseInOutCubic(k14SubRange(safeProgress, 0.80, 0.96));
    vertAlpha = vertFadeIn;
    railX = k14Lerp(0.340, 0.245, vertFadeIn);
  }

  if (vertAlpha > 0.01) {
    const railH = 0.245;
    ctx.save();
    ctx.globalAlpha = 0.78 * vertAlpha;
    ctx.strokeStyle = K14_PALETTE.peachWarm;
    ctx.lineWidth = 0.0045;
    ctx.beginPath();
    ctx.moveTo(-railX - 0.018, -railH);
    ctx.lineTo(-railX, -railH);
    ctx.lineTo(-railX, railH);
    ctx.lineTo(-railX - 0.018, railH);
    ctx.moveTo(railX + 0.018, -railH);
    ctx.lineTo(railX, -railH);
    ctx.lineTo(railX, railH);
    ctx.lineTo(railX + 0.018, railH);
    ctx.stroke();
    ctx.restore();
  }

  if (horizAlpha > 0.01) {
    const spanW = 0.53 * horizAlpha;
    const railY = 0.132;
    ctx.save();
    ctx.globalAlpha = 0.85 * horizAlpha;
    ctx.fillStyle = K14_PALETTE.peachWarm;
    ctx.fillRect(-spanW, -railY, spanW * 2, 0.006);
    ctx.fillRect(-spanW, railY - 0.006, spanW * 2, 0.006);

    ctx.font = '700 0.0145px Georgia, "Times New Roman", serif';
    ctx.fillStyle = K14_PALETTE.peachBright;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('FORWARD  TOGETHER  •  SEASON  2027', 0, railY + 0.038);
    ctx.restore();
  }

  /* 3. Render Every Individual Crisp Vector Letter */
  for (let i = 0; i < states.length; i++) {
    const st = states[i];
    ctx.save();
    ctx.translate(st.cx, st.cy);
    ctx.scale(st.sx, st.sy);
    k14DrawGlyphCentered(ctx, st.ch, K14_WORD_H, st.color);
    ctx.restore();
  }

  ctx.restore();
}

