const K13_TAU = Math.PI * 2;

function k13Clamp01(v) {
  return v < 0 ? 0 : (v > 1 ? 1 : v);
}

function k13Lerp(a, b, t) {
  return a + (b - a) * t;
}

function k13SubRange(t, a, b) {
  return k13Clamp01((t - a) / (b - a));
}

function k13EaseOutCubic(t) {
  const u = 1 - k13Clamp01(t);
  return 1 - u * u * u;
}

function k13EaseInCubic(t) {
  const u = k13Clamp01(t);
  return u * u * u;
}

function k13EaseInOutCubic(t) {
  const u = k13Clamp01(t);
  return u < 0.5 ? 4 * u * u * u : 1 - Math.pow(-2 * u + 2, 3) / 2;
}

function k13EaseOutQuint(t) {
  const u = 1 - k13Clamp01(t);
  return 1 - u * u * u * u * u;
