function k13MeasureStrWidth(str, h, gapRatio) {
  const gap = h * gapRatio;
  let w = 0;
  for (let i = 0; i < str.length; i++) {
    const ch = str[i];
    w += K13_GLYPHS[ch].w * h;
    if (i < str.length - 1 && ch !== ' ' && str[i + 1] !== ' ') w += gap;
  }
  return w;
}

function k13DrawVectorString(ctx, str, cx, cy, h, gapRatio, fillStyle, strokeStyle, strokeW) {
  const totalW = k13MeasureStrWidth(str, h, gapRatio);
  const gap = h * gapRatio;
  let cursor = cx - totalW * 0.5;
  const y0 = cy - h * 0.5;

  for (let i = 0; i < str.length; i++) {
    const ch = str[i];
    const g = K13_GLYPHS[ch];
    if (g.rings.length > 0) {
      ctx.beginPath();
      for (let r = 0; r < g.rings.length; r++) {
        const ring = g.rings[r];
        ctx.moveTo(cursor + ring[0][0] * h, y0 + ring[0][1] * h);
        for (let k = 1; k < ring.length; k++) {
          ctx.lineTo(cursor + ring[k][0] * h, y0 + ring[k][1] * h);
        }
        ctx.closePath();
      }
      ctx.fillStyle = fillStyle;
      ctx.fill('evenodd');
      if (strokeStyle && strokeW > 0) {
        ctx.lineWidth = strokeW;
        ctx.lineJoin = 'round';
        ctx.strokeStyle = strokeStyle;
        ctx.stroke();
      }
    }
    cursor += g.w * h;
    if (i < str.length - 1 && ch !== ' ' && str[i + 1] !== ' ') cursor += gap;
  }
}

/* Uniform Arc-Length Perimeter Sampler along Vector Glyphs */
function k13SampleLinePerimeter(lines, targetTotal) {
  const allSegs = [];
  let totalPerimeter = 0;

  for (let li = 0; li < lines.length; li++) {
    const ln = lines[li];
    const totalW = k13MeasureStrWidth(ln.text, ln.h, ln.gapRatio);
    const gap = ln.h * ln.gapRatio;
    let cursor = ln.cx - totalW * 0.5;
    const y0 = ln.cy - ln.h * 0.5;

    for (let i = 0; i < ln.text.length; i++) {
      const ch = ln.text[i];
      const g = K13_GLYPHS[ch];
      for (let r = 0; r < g.rings.length; r++) {
        const ring = g.rings[r];
        for (let k = 0; k < ring.length; k++) {
          const a = ring[k];
          const b = ring[(k + 1) % ring.length];
          const ax = cursor + a[0] * ln.h;
          const ay = y0 + a[1] * ln.h;
          const bx = cursor + b[0] * ln.h;
          const by = y0 + b[1] * ln.h;
          const len = Math.hypot(bx - ax, by - ay);
          if (len > 1e-6) {
            allSegs.push({ ax, ay, bx, by, cumEnd: totalPerimeter + len });
            totalPerimeter += len;
          }
        }
      }
      cursor += g.w * ln.h;
      if (i < ln.text.length - 1 && ch !== ' ' && ln.text[i + 1] !== ' ') cursor += gap;
    }
  }

  const pts = [];
  let sIdx = 0;
  for (let p = 0; p < targetTotal; p++) {
    const targetDist = ((p + 0.5) / targetTotal) * totalPerimeter;
    while (sIdx < allSegs.length - 1 && allSegs[sIdx].cumEnd < targetDist) {
      sIdx++;
    }
    const seg = allSegs[sIdx];
    const prevCum = sIdx === 0 ? 0 : allSegs[sIdx - 1].cumEnd;
    const segLen = seg.cumEnd - prevCum;
    const u = segLen > 1e-9 ? (targetDist - prevCum) / segLen : 0;
    pts.push({
      x: k13Lerp(seg.ax, seg.bx, u),
      y: k13Lerp(seg.ay, seg.by, u)
    });
  }
  return pts;
}

/* Precomputed Deterministic Particle Choreography (360 particles, C0/C1 seamless across all 4 scenes) */
const K13_PARTICLE_COUNT = 360;
const K13_CLUSTERS = [
  { cx: 0.00, cy: -0.05, sx: -0.04, sy: 0.39, t0: 0.02, tBurst: 0.24, rings: [36, 48, 60, 16], maxSpd: 0.31, baseHue: 0 },
  { cx: -0.39, cy: 0.00, sx: -0.44, sy: 0.39, t0: 0.06, tBurst: 0.28, rings: [26, 36, 38], maxSpd: 0.23, baseHue: 1 },
  { cx: 0.39, cy: 0.00, sx: 0.44, sy: 0.39, t0: 0.10, tBurst: 0.32, rings: [26, 36, 38], maxSpd: 0.23, baseHue: 1 }
];

const K13_DATA = (function () {
  /* Build Scene 0 chrysanthemum burst particles (localP runs [0..1] on [tBurstSec..5.0s]) */
  const rawParticles = [];
  let pGlobal = 0;
  for (let c = 0; c < K13_CLUSTERS.length; c++) {
    const cl = K13_CLUSTERS[c];
    const tBurstSec = cl.tBurst * 5.0;
    const burstDurSec = 5.0 - tBurstSec;
    for (let r = 0; r < cl.rings.length; r++) {
      const cnt = cl.rings[r];
      const fracR = (r + 1) / cl.rings.length;
      const spd = cl.maxSpd * (0.28 + 0.72 * fracR);
      const isGold = ((r + cl.baseHue) % 2 === 0);
      for (let k = 0; k < cnt; k++) {
        const phi = ((k + 0.5 * (r % 2)) / cnt) * K13_TAU;
        const micro = (((pGlobal * 73) % 19) - 9) * 0.004;
        const sMul = 1.0 + (((pGlobal * 37) % 13) - 6) * 0.015;
        const vx = Math.cos(phi + micro) * spd * sMul;
        const vy = Math.sin(phi + micro) * spd * sMul;
        const drag = 1.05;
        const grav = 0.048;
        /* Exact match with k13EvalBurstPos at tau = 1.0 (t = 5.0s) */
        const dispEnd = (1 - Math.exp(-drag)) / drag;
        const endX = cl.cx + vx * dispEnd;
        const endY = cl.cy + vy * dispEnd + 0.5 * grav;
        /* Exact velocity derivative dPos/dt (units/sec) at t = 5.0s */
        const dTauDt = 1.0 / burstDurSec;
        const endVxSec = vx * Math.exp(-drag) * dTauDt;
        const endVySec = (vy * Math.exp(-drag) + grav) * dTauDt;

        rawParticles.push({
          id: pGlobal,
          clusterIdx: c,
          tBurst: cl.tBurst,
          tBurstSec,
          burstDurSec,
          cx: cl.cx,
          cy: cl.cy,
          vx,
          vy,
          drag,
          grav,
          s0EndX: endX,
          s0EndY: endY,
          s0EndVxSec: endVxSec,
          s0EndVySec: endVySec,
          isGold,
          color: isGold ? K13_PALETTE.goldBright : K13_PALETTE.emeraldLight,
          radius: 0.0022 + (pGlobal % 3) * 0.00065,
          swirl: ((pGlobal % 2 === 0 ? 1 : -1) * (0.036 + (pGlobal % 5) * 0.010))
        });
        pGlobal++;
      }
    }
  }

  /* Sample clean perimeter targets for Scene 1 ("2027") & Scene 3 ("HAPPY NEW YEAR") */
  const targets2027 = k13SampleLinePerimeter(
    [{ text: '2027', cx: 0, cy: 0.00, h: 0.255, gapRatio: 0.14 }],
    K13_PARTICLE_COUNT
  );
  const targetsHNY = k13SampleLinePerimeter(
    [
      { text: 'HAPPY', cx: 0, cy: -0.095, h: 0.125, gapRatio: 0.22 },
      { text: 'NEW YEAR', cx: 0, cy: 0.075, h: 0.125, gapRatio: 0.18 }
    ],
    K13_PARTICLE_COUNT
  );

  /* Spatial order-matching to guarantee clean non-tangled converging particle flows */
  const sortOrderS0 = rawParticles.map((p, i) => ({ i, key: p.s0EndX * 1.4 + p.s0EndY * 0.45 }))
    .sort((a, b) => a.key - b.key);
  const sortOrderT1 = targets2027.map((t, i) => ({ i, key: t.x * 1.4 + t.y * 0.45 }))
    .sort((a, b) => a.key - b.key);

  for (let rank = 0; rank < K13_PARTICLE_COUNT; rank++) {
    const p = rawParticles[sortOrderS0[rank].i];
    const tgt = targets2027[sortOrderT1[rank].i];
    p.t1X = tgt.x;
    p.t1Y = tgt.y;

    /* Scene 2 firework #2: organized emerald-gold sunburst with smooth zero-slope takeoff */
    const dirAng = Math.atan2(tgt.y, tgt.x * 0.65) + (((p.id * 29) % 11) - 5) * 0.04;
    const radSpd = 0.17 + ((p.id * 41) % 10) * 0.014;
    const s2vx = Math.cos(dirAng) * radSpd;
    const s2vy = Math.sin(dirAng) * radSpd - 0.022;
    const s2Drag = 1.05;
    const s2Grav = 0.045;
    const s2Disp = (1 - Math.exp(-s2Drag)) / s2Drag;
    p.s2vx = s2vx;
    p.s2vy = s2vy;
    p.s2Drag = s2Drag;
    p.s2Grav = s2Grav;
    p.s2EndX = tgt.x + s2vx * s2Disp;
    p.s2EndY = tgt.y + s2vy * s2Disp + 0.5 * s2Grav;
    /* d(tau2)/dt at t=15.0s for tau2 = 0.5*(3*u^2 - u^3) is (3 - 3/2)/5 = 0.30 */
    const dTau2Dt = 0.30;
    p.s2EndVxSec = s2vx * Math.exp(-s2Drag) * dTau2Dt;
    p.s2EndVySec = (s2vy * Math.exp(-s2Drag) + s2Grav) * dTau2Dt;
  }

  /* Match Scene 2 end positions smoothly to Scene 3 "HAPPY NEW YEAR" targets */
  const sortOrderS2 = rawParticles.map((p, i) => ({ i, key: p.s2EndX + p.s2EndY * 1.65 }))
    .sort((a, b) => a.key - b.key);
  const sortOrderT3 = targetsHNY.map((t, i) => ({ i, key: t.x + t.y * 1.65 }))
    .sort((a, b) => a.key - b.key);

  for (let rank = 0; rank < K13_PARTICLE_COUNT; rank++) {
    const p = rawParticles[sortOrderS2[rank].i];
    const tgt = targetsHNY[sortOrderT3[rank].i];
    p.t3X = tgt.x;
    p.t3Y = tgt.y;
    p.fallDrop = 0.085 + ((p.id * 19) % 7) * 0.022;
