  return rawParticles;
})();

function k13EvalBurstPos(p, localP) {
  const tau = localP < 0 ? 0 : (localP > 1 ? 1 : localP);
  const disp = (1 - Math.exp(-p.drag * tau)) / p.drag;
  return {
    x: p.cx + p.vx * disp,
    y: p.cy + p.vy * disp + 0.5 * p.grav * tau * tau
  };
}

function k13EvalScene2Pos(p, localP) {
  const u = localP < 0 ? 0 : (localP > 1 ? 1 : localP);
  const tau = (3 * u * u - u * u * u) * 0.5;
  const disp = (1 - Math.exp(-p.s2Drag * tau)) / p.s2Drag;
  return {
    x: p.t1X + p.s2vx * disp,
    y: p.t1Y + p.s2vy * disp + 0.5 * p.s2Grav * tau * tau
  };
}

/* Continuous C0 + C1 Particle State Evaluator Across [0..20s] Global Loop Timeline */
function k13EvalGlobalParticle(p, loopSec, type1Alpha, type3Alpha) {
  if (loopSec < p.tBurstSec) {
    return { active: false, x: p.cx, y: p.cy, alpha: 0 };
  }
  if (loopSec < 5.0) {
    const tau = (loopSec - p.tBurstSec) / p.burstDurSec;
    const pos = k13EvalBurstPos(p, tau);
    return { active: true, x: pos.x, y: pos.y, alpha: k13Clamp01(tau / 0.08) * 0.94 };
  }
  if (loopSec < 10.0) {
    const dt = loopSec - 5.0;
    const gatherDur = 2.6;
    const alpha = 0.94 - 0.34 * type1Alpha;
    if (dt >= gatherDur) {
      return { active: true, x: p.t1X, y: p.t1Y, alpha };
    }
    const u = dt / gatherDur;
    const u2 = u * u;
    const u3 = u2 * u;
    const h00 = 2 * u3 - 3 * u2 + 1;
    const h10 = u3 - 2 * u2 + u;
    const h01 = -2 * u3 + 3 * u2;
    const sw = Math.sin(Math.PI * u);
    const sw2 = sw * sw;
    return {
      active: true,
      x: h00 * p.s0EndX + h10 * (gatherDur * p.s0EndVxSec) + h01 * p.t1X + Math.cos(u * Math.PI + p.id) * p.swirl * 0.45 * sw2,
      y: h00 * p.s0EndY + h10 * (gatherDur * p.s0EndVySec) + h01 * p.t1Y + Math.sin(u * Math.PI + p.id) * p.swirl * 0.45 * sw2,
      alpha
    };
  }
  if (loopSec < 15.0) {
    const u2 = (loopSec - 10.0) / 5.0;
    const pos = k13EvalScene2Pos(p, u2);
    return { active: true, x: pos.x, y: pos.y, alpha: 0.94 };
  }
  const dt3 = loopSec - 15.0;
  const gatherDur3 = 2.4;
  const p3 = dt3 / 5.0;
  const fallU = k13EaseInCubic(k13SubRange(p3, 0.78, 0.96));
  const masterFade = 1 - k13EaseOutCubic(k13SubRange(p3, 0.82, 0.96));
  const alpha = (0.94 - 0.36 * type3Alpha) * masterFade;

  let baseX = p.t3X;
  let baseY = p.t3Y;
  if (dt3 < gatherDur3) {
    const u = dt3 / gatherDur3;
    const u2 = u * u;
    const u3 = u2 * u;
    const h00 = 2 * u3 - 3 * u2 + 1;
    const h10 = u3 - 2 * u2 + u;
    const h01 = -2 * u3 + 3 * u2;
    const sw = Math.sin(Math.PI * u);
    const sw2 = sw * sw;
    baseX = h00 * p.s2EndX + h10 * (gatherDur3 * p.s2EndVxSec) + h01 * p.t3X + Math.cos(u * Math.PI + p.id) * p.swirl * 0.35 * sw2;
    baseY = h00 * p.s2EndY + h10 * (gatherDur3 * p.s2EndVySec) + h01 * p.t3Y + Math.sin(u * Math.PI + p.id) * p.swirl * 0.35 * sw2;
  }
  return {
    active: masterFade > 0.005,
    x: baseX,
    y: baseY + p.fallDrop * fallU,
    alpha
  };
}

function k13DrawParticleTrail(ctx, pts, color, radius, alpha) {
  if (alpha <= 0.01) return;
  ctx.save();
  ctx.globalAlpha *= alpha;
  if (pts.length >= 2) {
    ctx.beginPath();
    ctx.moveTo(pts[0].x, pts[0].y);
    for (let i = 1; i < pts.length; i++) {
      ctx.lineTo(pts[i].x, pts[i].y);
    }
    ctx.lineWidth = radius * 1.35;
    ctx.lineCap = 'round';
    ctx.strokeStyle = color;
    ctx.globalAlpha *= 0.42;
    ctx.stroke();
  }
  const head = pts[pts.length - 1];
  ctx.globalAlpha = alpha;
  ctx.beginPath();
  ctx.arc(head.x, head.y, radius, 0, K13_TAU);
  ctx.fillStyle = color;
  ctx.fill();
  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const safeLoopT = loopT < 0 ? loopT + duration : loopT;
  const safeScene = ((currentScene % sceneCount) + sceneCount) % sceneCount;
  const safeProgress = sceneProgress < 0 ? sceneProgress + 1 : sceneProgress;

  const U = Math.min(height, width / (16 / 9));
  const halfW = (width / U) * 0.5;

  ctx.save();
  ctx.shadowBlur = 0;

  /* 1. Deep Emerald-Black Dusk Linear Backdrop (Strictly NO background glow) */
  const bgGrad = ctx.createLinearGradient(0, 0, 0, height);
  bgGrad.addColorStop(0.0, K13_PALETTE.bgTop);
  bgGrad.addColorStop(0.58, K13_PALETTE.bgMid);
  bgGrad.addColorStop(1.0, K13_PALETTE.bgBottom);
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);

  ctx.translate(width * 0.5, height * 0.5);
  ctx.scale(U, U);

  /* Shared Gold & Emerald Hero Gradients */
  const heroGoldGrad = ctx.createLinearGradient(0, -0.14, 0, 0.14);
  heroGoldGrad.addColorStop(0.0, K13_PALETTE.goldBright);
  heroGoldGrad.addColorStop(0.45, K13_PALETTE.goldCore);
  heroGoldGrad.addColorStop(1.0, K13_PALETTE.goldWarm);

  const heroEmeraldGrad = ctx.createLinearGradient(0, -0.02, 0, 0.15);
  heroEmeraldGrad.addColorStop(0.0, K13_PALETTE.emeraldLight);
  heroEmeraldGrad.addColorStop(0.55, K13_PALETTE.emeraldCore);
  heroEmeraldGrad.addColorStop(1.0, K13_PALETTE.emeraldDeep);

  /* Compute type visibility envelopes deterministically across scenes */
  let type1Alpha = 0;
  let type3Alpha = 0;
  if (safeScene === 1) {
    type1Alpha = k13EaseInOutCubic(k13SubRange(safeProgress, 0.36, 0.54)) *
                 (1 - k13EaseInOutCubic(k13SubRange(safeProgress, 0.82, 0.96)));
  } else if (safeScene === 3) {
    type3Alpha = k13EaseInOutCubic(k13SubRange(safeProgress, 0.36, 0.52)) *
                 (1 - k13EaseInOutCubic(k13SubRange(safeProgress, 0.76, 0.88)));
  }

  if (safeScene === 0) {
    /* SCENE 0 (0.0 - 5.0s): Graceful Parabolic Rockets */
    for (let c = 0; c < K13_CLUSTERS.length; c++) {
      const cl = K13_CLUSTERS[c];
      if (safeProgress > cl.t0 && safeProgress < cl.tBurst + 0.06) {
        const asc = k13EaseOutCubic(k13SubRange(safeProgress, cl.t0, cl.tBurst));
        const fadeTail = 1 - k13Clamp01((safeProgress - cl.tBurst) / 0.05);
        const rx = k13Lerp(cl.sx, cl.cx, asc);
        const ry = k13Lerp(cl.sy, cl.cy, asc) - Math.sin(asc * Math.PI) * 0.055;
        const tailAsc = Math.max(0, asc - 0.18);
        const tx = k13Lerp(cl.sx, cl.cx, tailAsc);
        const ty = k13Lerp(cl.sy, cl.cy, tailAsc) - Math.sin(tailAsc * Math.PI) * 0.055;

        ctx.save();
        ctx.globalAlpha = 0.88 * fadeTail;
        const rGrad = ctx.createLinearGradient(tx, ty, rx, ry);
        rGrad.addColorStop(0, 'rgba(244, 201, 93, 0)');
        rGrad.addColorStop(1, K13_PALETTE.goldBright);
        ctx.beginPath();
        ctx.moveTo(tx, ty);
        ctx.lineTo(rx, ry);
        ctx.lineWidth = 0.0042;
        ctx.lineCap = 'round';
        ctx.strokeStyle = rGrad;
        ctx.stroke();

        ctx.beginPath();
        ctx.arc(rx, ry, 0.0052, 0, K13_TAU);
        ctx.fillStyle = K13_PALETTE.goldBright;
        ctx.fill();
        ctx.restore();
      }
    }
  } else if (safeScene === 1 && type1Alpha > 0.005) {
    /* SCENE 1 Hero Typography ("2027") */
    const ruleW = 0.42 * k13EaseOutCubic(k13SubRange(safeProgress, 0.40, 0.62));
    ctx.save();
    ctx.globalAlpha = 0.72 * type1Alpha;
    ctx.strokeStyle = K13_PALETTE.goldCore;
    ctx.lineWidth = 0.0022;
    ctx.beginPath();
    ctx.moveTo(-ruleW, -0.175);
    ctx.lineTo(ruleW, -0.175);
    ctx.moveTo(-ruleW, 0.175);
    ctx.lineTo(ruleW, 0.175);
    ctx.stroke();

    ctx.font = '600 0.016px Georgia, "Times New Roman", serif';
    ctx.fillStyle = K13_PALETTE.emeraldLight;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('CELEBRATING  NEW  HORIZONS', 0, 0.215);
    ctx.restore();

    ctx.save();
    ctx.globalAlpha = type1Alpha;
    k13DrawVectorString(ctx, '2027', 0, 0, 0.255, 0.14, heroGoldGrad, K13_PALETTE.goldBright, 0.0024);
    ctx.restore();
  } else if (safeScene === 2) {
    /* SCENE 2 Shockwave Accent Ring Strictly After Soft Launch */
    const ringU = k13EaseOutQuint(k13SubRange(safeProgress, 0.08, 0.74));
    const ringA = Math.sin(Math.PI * ringU) * 0.50;
    if (ringA > 0.01) {
      const rr = k13Lerp(0.08, 0.42, ringU);
      ctx.save();
      ctx.globalAlpha = ringA;
      ctx.beginPath();
      ctx.arc(0, 0, rr, 0, K13_TAU);
      ctx.lineWidth = 0.0028;
      ctx.strokeStyle = K13_PALETTE.emeraldLight;
      ctx.stroke();
      ctx.restore();
    }
  } else if (safeScene === 3 && type3Alpha > 0.005) {
    /* SCENE 3 Hero Typography ("HAPPY NEW YEAR" + "2027") */
    const ruleW = 0.48 * k13EaseOutCubic(k13SubRange(safeProgress, 0.40, 0.60));
    ctx.save();
    ctx.globalAlpha = type3Alpha;
    k13DrawVectorString(ctx, 'HAPPY', 0, -0.095, 0.125, 0.22, heroGoldGrad, K13_PALETTE.goldBright, 0.0018);
    k13DrawVectorString(ctx, 'NEW YEAR', 0, 0.075, 0.125, 0.18, heroEmeraldGrad, K13_PALETTE.emeraldLight, 0.0018);

    ctx.strokeStyle = 'rgba(244, 201, 93, 0.65)';
    ctx.lineWidth = 0.002;
    ctx.beginPath();
    ctx.moveTo(-ruleW, 0.178);
    ctx.lineTo(ruleW, 0.178);
    ctx.stroke();

    k13DrawVectorString(ctx, '2027', 0, 0.232, 0.052, 0.26, K13_PALETTE.goldBright, null, 0);
    ctx.restore();
  }

  /* Unified Continuous C0/C1 Particle & Trail Layer (Trails cross scene boundaries seamlessly!) */
  const trailDt = 0.14;
  for (let i = 0; i < K13_PARTICLE_COUNT; i++) {
    const p = K13_DATA[i];
    const now = k13EvalGlobalParticle(p, safeLoopT, type1Alpha, type3Alpha);
    if (!now.active || now.alpha <= 0.005) continue;
    const prevT = Math.max(p.tBurstSec, safeLoopT - trailDt);
    const prev = k13EvalGlobalParticle(p, prevT, type1Alpha, type3Alpha);
    k13DrawParticleTrail(ctx, [prev, now], p.color, p.radius, now.alpha);
  }

  ctx.restore();
}

