  mutedBlack: 'rgba(14, 12, 13, 0.45)',
  mutedWhite: 'rgba(246, 243, 238, 0.48)'
};

const K12_TAU = Math.PI * 2;

function k12Clamp01(v) {
  return v < 0 ? 0 : (v > 1 ? 1 : v);
}

function k12Lerp(a, b, t) {
  return a + (b - a) * t;
}

function k12SubRange(p, s, e) {
  return k12Clamp01((p - s) / (e - s));
}

function k12EaseOutCubic(t) {
  const u = 1 - k12Clamp01(t);
  return 1 - u * u * u;
}

function k12EaseInCubic(t) {
  const u = k12Clamp01(t);
  return u * u * u;
}

function k12EaseOutQuint(t) {
  const u = 1 - k12Clamp01(t);
  return 1 - u * u * u * u * u;
}

function k12EaseInQuint(t) {
  const u = k12Clamp01(t);
  return u * u * u * u * u;
}

function k12EaseInOutCubic(t) {
  const u = k12Clamp01(t);
  return u < 0.5 ? 4 * u * u * u : 1 - Math.pow(-2 * u + 2, 3) / 2;
}

function k12SampleCubic(p0, c1, c2, p1, steps) {
  const pts = [];
  for (let i = 1; i <= steps; i++) {
    const t = i / steps;
    const mt = 1 - t;
    const x = mt * mt * mt * p0[0] + 3 * mt * mt * t * c1[0] + 3 * mt * t * t * c2[0] + t * t * t * p1[0];
    const y = mt * mt * mt * p0[1] + 3 * mt * mt * t * c1[1] + 3 * mt * t * t * c2[1] + t * t * t * p1[1];
    pts.push([x, y]);
  }
  return pts;
}

function k12BuildSuperEllipseRing(cx, cy, rx, ry, power, steps) {
  const pts = [];
  for (let i = 0; i < steps; i++) {
    const a = (i / steps) * K12_TAU;
    const ca = Math.cos(a);
    const sa = Math.sin(a);
    const x = cx + Math.sign(ca) * Math.pow(Math.abs(ca), 2 / power) * rx;
    const y = cy + Math.sign(sa) * Math.pow(Math.abs(sa), 2 / power) * ry;
    pts.push([x, y]);
  }
  return pts;
}

