function k12MeasureTextWidth(str, h, gapRatio) {
  const gap = h * gapRatio;
  let w = 0;
  for (let i = 0; i < str.length; i++) {
    const ch = str[i];
    w += K12_GLYPHS[ch].w * h;
    if (i < str.length - 1 && ch !== ' ' && str[i + 1] !== ' ') {
      w += gap;
    }
  }
  return w;
}

function k12DrawVectorString(ctx, str, cx, cy, h, gapRatio, color, perCharColors) {
  const totalW = k12MeasureTextWidth(str, h, gapRatio);
  const gap = h * gapRatio;
  let cursor = cx - totalW * 0.5;
  const y0 = cy - h * 0.5;

  for (let i = 0; i < str.length; i++) {
    const ch = str[i];
    const g = K12_GLYPHS[ch];
    const gw = g.w * h;
    if (g.rings.length > 0) {
      ctx.save();
      ctx.translate(cursor, y0);
      ctx.scale(h, h);
      ctx.beginPath();
      for (let r = 0; r < g.rings.length; r++) {
        const pts = g.rings[r];
        ctx.moveTo(pts[0][0], pts[0][1]);
        for (let k = 1; k < pts.length; k++) {
          ctx.lineTo(pts[k][0], pts[k][1]);
        }
        ctx.closePath();
      }
      ctx.fillStyle = (perCharColors && perCharColors[i]) ? perCharColors[i] : color;
      ctx.fill('evenodd');
      ctx.restore();
    }
    cursor += gw;
    if (i < str.length - 1 && ch !== ' ' && str[i + 1] !== ' ') {
      cursor += gap;
    }
  }
}

/* Broadcast countdown themes cycling cleanly across Black, Crimson, Ivory-White */
const K12_COUNTDOWN_BEATS = [
  { scene: 0, idx: 0, label: '10', bg: K12_PALETTE.black, fg: K12_PALETTE.white, accent: K12_PALETTE.crimson, wipeDir: 0 },
