  { scene: 1, idx: 0, label: '7',  bg: K12_PALETTE.black, fg: K12_PALETTE.white, accent: K12_PALETTE.crimson, wipeDir: 3 },
  { scene: 1, idx: 1, label: '6',  bg: K12_PALETTE.crimson, fg: K12_PALETTE.white, accent: K12_PALETTE.black, wipeDir: 0 },
  { scene: 1, idx: 2, label: '5',  bg: K12_PALETTE.white, fg: K12_PALETTE.black, accent: K12_PALETTE.crimson, wipeDir: 1 },
  { scene: 2, idx: 0, label: '4',  bg: K12_PALETTE.black, fg: K12_PALETTE.white, accent: K12_PALETTE.crimson, wipeDir: 2 },
  { scene: 2, idx: 1, label: '3',  bg: K12_PALETTE.crimson, fg: K12_PALETTE.white, accent: K12_PALETTE.black, wipeDir: 3 },
  { scene: 2, idx: 2, label: '2',  bg: K12_PALETTE.white, fg: K12_PALETTE.black, accent: K12_PALETTE.crimson, wipeDir: 0 },
  { scene: 3, idx: 0, label: '1',  bg: K12_PALETTE.black, fg: K12_PALETTE.white, accent: K12_PALETTE.crimson, wipeDir: 1 },
  { scene: 3, idx: 1, label: '0',  bg: K12_PALETTE.crimson, fg: K12_PALETTE.white, accent: K12_PALETTE.white, wipeDir: 2 }
];

function k12FillWipeRect(ctx, width, height, color, frac, dir) {
  const f = k12Clamp01(frac);
  if (f <= 0.001) return;
  ctx.fillStyle = color;
  if (dir === 0) {
    ctx.fillRect(0, 0, width * f, height);
  } else if (dir === 1) {
    ctx.fillRect(0, 0, width, height * f);
  } else if (dir === 2) {
    const w = width * f;
    ctx.fillRect(width - w, 0, w, height);
  } else {
    const h = height * f;
    ctx.fillRect(0, height - h, width, h);
  }
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 5;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const safeLoopT = ((loopT % duration) + duration) % duration;
  const safeScene = Math.max(0, Math.min(sceneCount - 1, Math.floor(safeLoopT / sceneDuration)));
  const safeProgress = (safeLoopT % sceneDuration) / sceneDuration;

  const U = Math.min(height, width * (9 / 16));
  const halfW = (width * 0.5) / U;

  ctx.save();
  ctx.shadowBlur = 0;

  /* 1. Determine Active Countdown Beat or Scene 4 Finale State */
  let frameBg = K12_PALETTE.black;
  let frameFg = K12_PALETTE.white;
  let frameAccent = K12_PALETTE.crimson;
  let isLightBg = false;

  if (safeScene <= 3) {
    /* Scenes 0..2 have 3 beats (each ~1.33s); Scene 3 has 2 beats ('1' and climax '0') */
    const localCount = safeScene < 3 ? 3 : 2;
    const rawIdx = Math.min(localCount - 1, Math.floor(safeProgress * localCount));
    const beatP = (safeProgress * localCount) - rawIdx;
    const globalBeatIdx = safeScene < 3 ? (safeScene * 3 + rawIdx) : (9 + rawIdx);
    const curBeat = K12_COUNTDOWN_BEATS[globalBeatIdx];
    const prevBg = globalBeatIdx === 0 ? K12_PALETTE.black : K12_COUNTDOWN_BEATS[globalBeatIdx - 1].bg;

    /* Seamless directional wipe transition over previous beat background (zero boundary flash) */
    ctx.fillStyle = prevBg;
    ctx.fillRect(0, 0, width, height);
    const wipeU = k12EaseOutQuint(k12SubRange(beatP, 0.00, 0.18));
    k12FillWipeRect(ctx, width, height, curBeat.bg, wipeU, curBeat.wipeDir);

    frameBg = curBeat.bg;
    frameFg = curBeat.fg;
    frameAccent = curBeat.accent;
    isLightBg = frameBg === K12_PALETTE.white;

    ctx.translate(width * 0.5, height * 0.5);
    ctx.scale(U, U);

    /* Controlled Numeral & Circular Broadcast Ring (Strict Clearance Around Numeral Bounds) */
    const enterScale = k12EaseOutQuint(k12SubRange(beatP, 0.04, 0.30));
    const exitScale = k12EaseInQuint(k12SubRange(beatP, 0.84, 0.99));
    const numAlpha = enterScale * (1 - exitScale);

    /* Subtle controlled climax concentric pulse ONLY for beat '0' (zero shaky jitter!) */
    const isClimaxZero = globalBeatIdx === 10;
    const pulseBoom = isClimaxZero ? Math.sin(Math.PI * k12SubRange(beatP, 0.10, 0.55)) * 0.055 : 0;
    const numScale = k12Lerp(0.76, 1.0, enterScale) * (1 - 0.12 * exitScale) * (1 + pulseBoom);

    /* Outer broadcast timer ring stays cleanly at r = 0.295 (disjoint from max '10' half-diag 0.228) */
    const ringRadius = 0.295;
    const ringTrackAlpha = 0.22 * (1 - exitScale * 0.85);
    ctx.save();
    ctx.beginPath();
    ctx.arc(0, 0, ringRadius, 0, K12_TAU);
    ctx.lineWidth = 0.0045;
    ctx.strokeStyle = isLightBg ? K12_PALETTE.mutedBlack : K12_PALETTE.mutedWhite;
    ctx.globalAlpha *= ringTrackAlpha;
    ctx.stroke();
    ctx.restore();

    const arcProgress = k12EaseOutCubic(k12SubRange(beatP, 0.06, 0.84)) * (1 - k12EaseInCubic(k12SubRange(beatP, 0.86, 0.98)));
    if (arcProgress > 0.005) {
      ctx.save();
      ctx.beginPath();
      ctx.arc(0, 0, ringRadius, -Math.PI * 0.5, -Math.PI * 0.5 + K12_TAU * arcProgress);
      ctx.lineWidth = 0.011;
      ctx.lineCap = 'butt';
      ctx.strokeStyle = frameAccent;
      ctx.stroke();
      ctx.restore();
    }

    /* 12 Symmetric Radial Index Ticks Outside Ring (r = 0.320..0.340) */
    if (arcProgress > 0.01) {
      ctx.save();
      ctx.globalAlpha *= 0.55 * (1 - exitScale);
      for (let tk = 0; tk < 12; tk++) {
        const ang = (tk / 12) * K12_TAU - Math.PI * 0.5;
        const rIn = 0.318;
        const rOut = (tk % 3 === 0) ? 0.342 : 0.332;
        ctx.beginPath();
        ctx.moveTo(Math.cos(ang) * rIn, Math.sin(ang) * rIn);
        ctx.lineTo(Math.cos(ang) * rOut, Math.sin(ang) * rOut);
        ctx.lineWidth = tk % 3 === 0 ? 0.0038 : 0.0020;
        ctx.strokeStyle = frameFg;
        ctx.stroke();
      }
      ctx.restore();
    }

    /* Climax '0' Symmetric Expanding Wave Ring Strictly Bounded Inside Frame (r <= 0.39) */
    if (isClimaxZero) {
      const shockU = k12EaseOutCubic(k12SubRange(beatP, 0.14, 0.78));
      const shockA = Math.sin(Math.PI * shockU);
      if (shockA > 0.01) {
        const sr = k12Lerp(0.325, 0.395, shockU);
        ctx.save();
        ctx.globalAlpha *= shockA * 0.65;
        ctx.beginPath();
        ctx.arc(0, 0, sr, 0, K12_TAU);
        ctx.lineWidth = 0.0032;
        ctx.strokeStyle = K12_PALETTE.white;
        ctx.stroke();
        ctx.restore();
      }
    }

    /* Flanking Broadcast Progress Step Pills in Left/Right Lanes (|X| >= 0.54, zero collision with center ring) */
    const stepFrac = (10 - globalBeatIdx) / 10;
    const barH = 0.28;
    ctx.save();
    ctx.globalAlpha *= (1 - exitScale * 0.7);
    ctx.fillStyle = isLightBg ? 'rgba(14,12,13,0.16)' : 'rgba(246,243,238,0.18)';
    ctx.fillRect(-0.56, -barH * 0.5, 0.012, barH);
    ctx.fillRect(0.548, -barH * 0.5, 0.012, barH);
    ctx.fillStyle = frameAccent;
    const activeBarH = barH * (1 - stepFrac);
    ctx.fillRect(-0.56, barH * 0.5 - activeBarH, 0.012, activeBarH);
    ctx.fillRect(0.548, barH * 0.5 - activeBarH, 0.012, activeBarH);
    ctx.restore();

    /* Centered Giant Broadcast Numeral */
    if (numAlpha > 0.005) {
      const numH = curBeat.label === '10' ? 0.250 * numScale : 0.275 * numScale;
      ctx.save();
      ctx.globalAlpha *= numAlpha;
      k12DrawVectorString(ctx, curBeat.label, 0, 0, numH, 0.13, frameFg, null);
      ctx.restore();
    }
  } else {
    /* SCENE 4 (16.00 - 20.00s): Bold "HAPPY NEW YEAR" & "2027!" Showcase -> Seamless Reset to Black t=0 */
    const entryWipe = k12EaseOutQuint(k12SubRange(safeProgress, 0.00, 0.14));
    ctx.fillStyle = K12_PALETTE.crimson;
    ctx.fillRect(0, 0, width, height);
    k12FillWipeRect(ctx, width, height, K12_PALETTE.black, entryWipe, 0);

    frameBg = K12_PALETTE.black;
    frameFg = K12_PALETTE.white;
    frameAccent = K12_PALETTE.crimson;

    ctx.translate(width * 0.5, height * 0.5);
    ctx.scale(U, U);

    const ribbonOpen = k12EaseOutQuint(k12SubRange(safeProgress, 0.10, 0.34));
    const ribbonTextSlide = k12Lerp(0.18, 0.0, k12EaseOutQuint(k12SubRange(safeProgress, 0.14, 0.38)));
