function k11EaseInCubic(t) {
  const u = k11Clamp01(t);
  return u * u * u;
}

function k11EaseInOutCubic(t) {
  const u = k11Clamp01(t);
  return u < 0.5 ? 4 * u * u * u : 1 - Math.pow(-2 * u + 2, 3) / 2;
