/* Evaluates strictly non-crossing vertical Y for wave lane 0 (top), 1 (mid), 2 (bot) */
function k11EvalLaneY(laneIdx, x, cycle, morphAmt, spreadOut) {
  const ph1 = cycle * K11_TAU * 3;
  const ph2 = cycle * K11_TAU * 2;
  const baseSpacing = 0.156 + spreadOut * 0.104;
  const baseY = (laneIdx - 1) * baseSpacing;

