    return baseY + k11Lerp(calm, harmonic, morphAmt);
  }
  if (laneIdx === 1) {
    const calm = Math.sin(x * 3.8 + ph1 + 0.25) * 0.024;
    const harmonic = -Math.sin(x * 4.8 + ph1 + 1.1) * 0.030;
    return baseY + k11Lerp(calm, harmonic, morphAmt);
