  const calm = Math.sin(x * 3.8 + ph1 + 0.50) * 0.024;
  const harmonic = Math.sin(x * 5.2 - ph1 + 2.0) * 0.036 - Math.cos(x * 8.6 + ph2) * 0.011;
  return baseY + k11Lerp(calm, harmonic, morphAmt);
