/* Builds x=0-anchored arc-length lookup table for tangent-accurate wave sampling */
function k11BuildWaveLUT(laneIdx, xMin, xMax, steps, cycle, morphAmt, spreadOut) {
  const pts = [];
  let sAccum = 0;
  let midS = 0;
  let prevX = xMin;
  let prevY = k11EvalLaneY(laneIdx, xMin, cycle, morphAmt, spreadOut);
  pts.push({ x: prevX, y: prevY, s: 0 });

  for (let i = 1; i <= steps; i++) {
    const x = k11Lerp(xMin, xMax, i / steps);
    const y = k11EvalLaneY(laneIdx, x, cycle, morphAmt, spreadOut);
    sAccum += Math.hypot(x - prevX, y - prevY);
    pts.push({ x, y, s: sAccum });
    if (prevX <= 0 && x >= 0) {
      const frac = x !== prevX ? (0 - prevX) / (x - prevX) : 0;
      midS = pts[i - 1].s + frac * (sAccum - pts[i - 1].s);
    }
    prevX = x;
    prevY = y;
  }

  for (let i = 0; i < pts.length; i++) {
    pts[i].sd = pts[i].s - midS;
  }
  return pts;
}

function k11SampleLUTAtSignedArc(lut, sdTarget) {
  const n = lut.length;
  if (sdTarget < lut[0].sd || sdTarget > lut[n - 1].sd) return null;
  let lo = 0;
  let hi = n - 1;
  while (hi - lo > 1) {
    const mid = (lo + hi) >> 1;
    if (lut[mid].sd <= sdTarget) lo = mid;
    else hi = mid;
  }
  const p0 = lut[lo];
  const p1 = lut[hi];
  const seg = p1.sd - p0.sd;
  const u = seg > 1e-7 ? (sdTarget - p0.sd) / seg : 0;
  const x = k11Lerp(p0.x, p1.x, u);
  const y = k11Lerp(p0.y, p1.y, u);
  const ang = Math.atan2(p1.y - p0.y, p1.x - p0.x);
  return { x, y, ang };
}

