  const laneConfigs = [
    { dir: 1, turns: 3, color: K11_PALETTE.peachBright, guideColor: K11_PALETTE.ribbonGuide },
    { dir: -1, turns: 3, color: K11_PALETTE.coralSoft, guideColor: K11_PALETTE.ribbonGuide },
    { dir: 1, turns: 3, color: K11_PALETTE.violetSoft, guideColor: K11_PALETTE.ribbonGuide }
  ];

  const lutXMin = -innerClipX - 0.06;
  const lutXMax = innerClipX + 0.06;

  for (let lane = 0; lane < 3; lane++) {
    const laneAlpha = lane === 1 ? midWaveAlpha : outerWaveAlpha;
    if (laneAlpha <= 0.005) continue;

    const cfg = laneConfigs[lane];
    const lut = k11BuildWaveLUT(lane, lutXMin, lutXMax, 136, cycle, morphAmt, spreadOut);

    /* Subtle clean ribbon baseline parallel beneath wave letters (distinct offset) */
    ctx.save();
    ctx.globalAlpha *= laneAlpha * 0.55;
    ctx.beginPath();
    for (let i = 0; i < lut.length; i++) {
      const gx = lut[i].x;
      const gy = lut[i].y + K11_LANE_GLYPH_H * 0.92;
      if (i === 0) ctx.moveTo(gx, gy);
      else ctx.lineTo(gx, gy);
    }
    ctx.lineWidth = 0.0016;
    ctx.strokeStyle = cfg.guideColor;
    ctx.stroke();
    ctx.restore();

    /* Exact periodic arc-length marquee wrapping guarantees t=0 === t=20 seam */
    const rep = K11_PHRASE_LAYOUT.repeatLen;
    const minSd = lut[0].sd - rep;
    const maxSd = lut[lut.length - 1].sd + rep;
    const scrollShift = ((cycle * cfg.turns) % 1.0) * rep * cfg.dir;
    const kStart = Math.floor((minSd - scrollShift) / rep);
    const kEnd = Math.ceil((maxSd - scrollShift) / rep);

    for (let k = kStart; k <= kEnd; k++) {
      const baseSd = k * rep + scrollShift;
      for (let gIdx = 0; gIdx < K11_PHRASE_LAYOUT.glyphs.length; gIdx++) {
        const gItem = K11_PHRASE_LAYOUT.glyphs[gIdx];
        if (gItem.ch === ' ') continue;
        const targetSd = baseSd + gItem.offset;
        const sample = k11SampleLUTAtSignedArc(lut, targetSd);
        if (!sample) continue;

        /* Smooth horizontal aperture fade near frame sides so letters never slice awkwardly */
        const edgeDist = innerClipX - Math.abs(sample.x);
        const edgeFade = k11Clamp01(edgeDist / 0.09);
        const charAlpha = laneAlpha * edgeFade;
        if (charAlpha <= 0.008) continue;

        ctx.save();
        ctx.globalAlpha *= charAlpha;
        ctx.translate(sample.x, sample.y);
        ctx.rotate(sample.ang);
        k11DrawWaveGlyph(ctx, gItem.ch, K11_LANE_GLYPH_H, cfg.color);
        ctx.restore();
      }
    }
  }
  ctx.restore();

  /* 4. Scene 2 Centerpiece "2027" & Framing Sunset Rules (Zero Overlap with Waves) */
  if (heroRulesGrow > 0.005) {
    const rw = 0.42 * heroRulesGrow;
    ctx.save();
    ctx.globalAlpha *= heroAlpha;
    ctx.fillStyle = K11_PALETTE.peachWarm;
    ctx.fillRect(-rw, -0.175, rw * 2, 0.0024);
    ctx.fillRect(-rw, 0.175, rw * 2, 0.0024);
    k11DrawDiamond(ctx, 0, -0.175, 0.0065 * heroRulesGrow);
    ctx.fillStyle = K11_PALETTE.peachBright;
    ctx.fill();
    k11DrawDiamond(ctx, 0, 0.175, 0.0065 * heroRulesGrow);
    ctx.fill();
    ctx.restore();
  }

  k11DrawHero2027(ctx, heroScale, heroAlpha);

  ctx.restore();
}

