    headerY: 0.129,
    title: 'SCHEDULED DEPARTURE // STATUS',
    tagRight: 'LIVE',
    tileW: 0.081,
    tileH: 0.096,
    pitch: 0.0945
  }
];

function k19MakeSequence(startCh, endCh, nSteps, salt) {
  if (nSteps <= 0) return [endCh];
  const seq = [startCh];
  for (let s = 1; s < nSteps; s++) {
    const idx = (salt * 7 + s * 11 + startCh.charCodeAt(0) * 3) % K19_SCRAMBLE_POOL.length;
    let ch = K19_SCRAMBLE_POOL[idx];
    if (ch === seq[seq.length - 1]) {
      ch = K19_SCRAMBLE_POOL[(idx + 5) % K19_SCRAMBLE_POOL.length];
    }
    seq.push(ch);
  }
  seq.push(endCh);
  return seq;
}

/* Precompute Continuous Split-Flap Cell Timelines across [0..20s] */
const K19_CELLS = (function () {
  const all = [];
  for (let r = 0; r < K19_ROWS_SPEC.length; r++) {
    const spec = K19_ROWS_SPEC[r];
    const len = spec.target.length;
    const totalW = (len - 1) * spec.pitch + spec.tileW;
    const startX = -totalW * 0.5 + spec.tileW * 0.5;

    for (let c = 0; c < len; c++) {
      const seedCh = spec.seed[c];
      const targCh = spec.target[c];
      const midCh = spec.mid1[c];
      const cx = startX + c * spec.pitch;
      const salt = r * 43 + c * 17 + 5;

      const phases = [];
      if (r === 0) {
        /* Scene 0: Scramble seedCh -> "DESTINATION: 2027" lock, hold Scenes 1-2, Scene 3 return to seedCh */
        const lockEnd = 2.6 + (c / (len - 1)) * 1.9;
        phases.push({ a: 0.10 + (c % 5) * 0.05, b: lockEnd, seq: k19MakeSequence(seedCh, targCh, 7 + (c % 4), salt) });
        const exitStart = 17.1 + ((len - 1 - c) / (len - 1)) * 1.0;
        phases.push({ a: exitStart, b: 19.65, seq: k19MakeSequence(targCh, seedCh, 5 + (c % 3), salt + 99) });
      } else if (r === 1) {
        /* Scene 0: Fast scramble seedCh -> midCh; Scene 1: Staggered lock midCh -> "HAPPY NEW YEAR"; Scene 3: Scramble -> seedCh */
        phases.push({ a: 0.15 + (c % 4) * 0.08, b: 4.85, seq: k19MakeSequence(seedCh, midCh, 8 + (c % 3), salt) });
        const lockStart = 5.15 + c * 0.16;
        const lockEnd = 6.80 + c * 0.18;
        phases.push({ a: lockStart, b: lockEnd, seq: k19MakeSequence(midCh, targCh, 6 + (c % 3), salt + 31) });
        const exitStart = 16.0 + ((len - 1 - c) / (len - 1)) * 1.1;
        phases.push({ a: exitStart, b: 19.45, seq: k19MakeSequence(targCh, seedCh, 6 + (c % 4), salt + 77) });
      } else {
        /* Scene 0-1: Roll seedCh -> midCh -> targCh early in Scene 2 -> Blink ON TIME in Scene 2 -> Scene 3 exit */
        phases.push({ a: 0.20 + (c % 4) * 0.08, b: 9.75, seq: k19MakeSequence(seedCh, midCh, 14 + (c % 4), salt + 12) });
        const lockStart = 10.05 + (c / (len - 1)) * 0.55;
        const lockEnd = 10.95 + (c / (len - 1)) * 0.65;
        phases.push({ a: lockStart, b: lockEnd, seq: k19MakeSequence(midCh, targCh, 4 + (c % 3), salt + 53) });
        const exitStart = 15.20 + (c / (len - 1)) * 0.90;
        phases.push({ a: exitStart, b: 19.00, seq: k19MakeSequence(targCh, seedCh, 7 + (c % 3), salt + 88) });
      }

      all.push({
        rowIdx: r,
        colIdx: c,
        cx,
        cy: spec.y,
        tileW: spec.tileW,
        tileH: spec.tileH,
        seedCh,
        targCh,
        phases
      });
    }
  }
  return all;
})();

function k19EvaluateCell(cell, loopT) {
  let activeCh = cell.seedCh;
  let nextCh = cell.seedCh;
  let flipU = 0;
  let locked = false;

  for (let i = 0; i < cell.phases.length; i++) {
    const ph = cell.phases[i];
    if (loopT >= ph.b) {
      activeCh = ph.seq[ph.seq.length - 1];
      nextCh = activeCh;
      flipU = 0;
      if (i === 0 && cell.rowIdx === 0) locked = true;
      if (i === 1 && (cell.rowIdx === 1 || cell.rowIdx === 2)) locked = true;
    } else if (loopT > ph.a) {
      const u = k19EaseInOutQuad((loopT - ph.a) / (ph.b - ph.a));
      const steps = ph.seq.length - 1;
      const pos = u * steps;
      const stepIdx = Math.min(steps - 1, Math.floor(pos));
      activeCh = ph.seq[stepIdx];
      nextCh = ph.seq[stepIdx + 1];
      flipU = pos - stepIdx;
      locked = false;
      break;
    } else {
      break;
    }
  }

  /* Row 0 unlocks cleanly at Scene 3 phase 1, Rows 1-2 unlock at Scene 3 phase 2 */
  const lastPh = cell.phases[cell.phases.length - 1];
  if (loopT >= lastPh.a) locked = false;

  return { activeCh, nextCh, flipU, locked };
}

function k19EvaluateBoardState(loopT) {
  const duration = 20;
  const sceneCount = 4;
  const sceneDuration = duration / sceneCount;
  const safeScene = Math.max(0, Math.min(3, Math.floor(loopT / sceneDuration)));
  const p = (loopT % sceneDuration) / sceneDuration;

  /* Blink envelope strictly bounded inside Scene 2 [11.75 .. 14.85s] (4 smooth LED blinks) */
  let blinkPulse = 0;
  let blinkEnv = 0;
  if (safeScene === 2 && loopT >= 11.75 && loopT <= 14.85) {
    const bu = (loopT - 11.75) / 3.10;
    blinkEnv = Math.sin(Math.PI * bu);
    blinkPulse = 0.5 - 0.5 * Math.cos(bu * K19_TAU * 4);
  }

  const cells = [];
  for (let i = 0; i < K19_CELLS.length; i++) {
    const c = K19_CELLS[i];
    const st = k19EvaluateCell(c, loopT);
    let col = K19_PALETTE.amber;
    if (c.rowIdx === 2 && st.locked && blinkEnv > 0.05) {
      if (c.colIdx <= 3 || (c.colIdx >= 7 && c.colIdx <= 13)) {
        col = blinkPulse > 0.46 ? K19_PALETTE.amberBright : K19_PALETTE.amberDim;
      }
    }
    cells.push({ cell: c, ...st, textColor: col });
  }

  return { safeScene, p, blinkPulse, blinkEnv, cells };
}

function k19TraceGlyph(ctx, ch, gx, gy, gw, gh) {
  const rings = K19_GLYPHS[ch];
  if (!rings || rings.length === 0) return false;
  ctx.beginPath();
  for (let r = 0; r < rings.length; r++) {
    const pts = rings[r];
    ctx.moveTo(gx + (pts[0][0] / 0.64) * gw, gy + pts[0][1] * gh);
    for (let i = 1; i < pts.length; i++) {
      ctx.lineTo(gx + (pts[i][0] / 0.64) * gw, gy + pts[i][1] * gh);
    }
    ctx.closePath();
  }
  return true;
}

function k19FillRoundedRect(ctx, x, y, w, h, r) {
  const rad = Math.min(r, w * 0.45, h * 0.45);
  ctx.beginPath();
  ctx.moveTo(x + rad, y);
  ctx.lineTo(x + w - rad, y);
  ctx.quadraticCurveTo(x + w, y, x + w, y + rad);
  ctx.lineTo(x + w, y + h - rad);
  ctx.quadraticCurveTo(x + w, y + h, x + w - rad, y + h);
  ctx.lineTo(x + rad, y + h);
  ctx.quadraticCurveTo(x, y + h, x, y + h - rad);
  ctx.lineTo(x, y + rad);
  ctx.quadraticCurveTo(x, y, x + rad, y);
  ctx.closePath();
}

function k19DrawSplitFlapCard(ctx, cell, state) {
  const { cx, cy, tileW, tileH } = cell;
  const { activeCh, nextCh, flipU, textColor } = state;
  const hw = tileW * 0.5;
  const hh = tileH * 0.5;
  const gap = tileH * 0.015;
  const gw = tileW * 0.62;
  const gh = tileH * 0.66;
  const gx = -gw * 0.5;
  const gy = -gh * 0.5;

  ctx.save();
  ctx.translate(cx, cy);

  /* Card Base Silhouette */
  k19FillRoundedRect(ctx, -hw, -hh, tileW, tileH, tileW * 0.08);
  ctx.fillStyle = K19_PALETTE.tileBot;
  ctx.fill();
  ctx.strokeStyle = K19_PALETTE.tileBorder;
  ctx.lineWidth = 0.0014;
  ctx.stroke();

  /* Subtle top flap tint */
  ctx.fillStyle = K19_PALETTE.tileTop;
  ctx.fillRect(-hw + 0.001, -hh + 0.001, tileW - 0.002, hh - gap * 0.5);

  const staticTopCh = flipU > 0.0001 ? nextCh : activeCh;
  const staticBotCh = activeCh;

  /* Static Top Half Clip */
  ctx.save();
  ctx.beginPath();
  ctx.rect(-hw, -hh, tileW, hh - gap * 0.5);
  ctx.clip();
  if (k19TraceGlyph(ctx, staticTopCh, gx, gy, gw, gh)) {
    ctx.fillStyle = textColor;
    ctx.fill('evenodd');
  }
  ctx.restore();

  /* Static Bottom Half Clip */
  ctx.save();
  ctx.beginPath();
  ctx.rect(-hw, gap * 0.5, tileW, hh - gap * 0.5);
  ctx.clip();
  if (k19TraceGlyph(ctx, staticBotCh, gx, gy, gw, gh)) {
    ctx.fillStyle = textColor;
    ctx.fill('evenodd');
  }
  ctx.restore();

  /* 2D ScaleY Mechanical Moving Flap Half */
  if (flipU > 0.0001 && flipU < 0.9999) {
    if (flipU < 0.5) {
      const sy = Math.cos(flipU * Math.PI);
      ctx.save();
      ctx.beginPath();
      ctx.rect(-hw, -hh, tileW, hh - gap * 0.5);
      ctx.clip();
      ctx.scale(1, Math.max(0.002, sy));
      ctx.fillStyle = K19_PALETTE.tileTop;
      ctx.fillRect(-hw, -hh, tileW, hh);
      if (k19TraceGlyph(ctx, activeCh, gx, gy, gw, gh)) {
        ctx.fillStyle = textColor;
        ctx.fill('evenodd');
      }
      ctx.fillStyle = 'rgba(0, 0, 0, ' + (0.36 * Math.sin(flipU * Math.PI)).toFixed(3) + ')';
      ctx.fillRect(-hw, -hh, tileW, hh);
      ctx.restore();
    } else {
      const sy = -Math.cos(flipU * Math.PI);
      ctx.save();
      ctx.beginPath();
      ctx.rect(-hw, gap * 0.5, tileW, hh - gap * 0.5);
      ctx.clip();
      ctx.scale(1, Math.max(0.002, sy));
      ctx.fillStyle = K19_PALETTE.tileBot;
      ctx.fillRect(-hw, 0, tileW, hh);
      if (k19TraceGlyph(ctx, nextCh, gx, gy, gw, gh)) {
        ctx.fillStyle = textColor;
        ctx.fill('evenodd');
      }
      ctx.fillStyle = 'rgba(0, 0, 0, ' + (0.32 * (1 - sy)).toFixed(3) + ')';
      ctx.fillRect(-hw, 0, tileW, hh);
      ctx.restore();
    }
  }

  /* Crisp Mechanical Center Split Line & Left/Right Hinge Pins */
  ctx.fillStyle = '#06070A';
  ctx.fillRect(-hw, -gap * 0.5, tileW, gap);
  ctx.fillStyle = K19_PALETTE.hingePin;
  ctx.fillRect(-hw + tileW * 0.03, -gap * 1.1, tileW * 0.06, gap * 2.2);
  ctx.fillRect(hw - tileW * 0.09, -gap * 1.1, tileW * 0.06, gap * 2.2);

  ctx.restore();
}

function k19DrawText(ctx, text, x, y, sizeU, weight, align, color, letterSpacingEm) {
  ctx.save();
  ctx.translate(x, y);
  ctx.scale(0.001, 0.001);
  ctx.fillStyle = color;
  ctx.textBaseline = 'middle';
  ctx.font = weight + ' ' + Math.round(sizeU * 1000) + 'px "Inter", "Plus Jakarta Sans", "Segoe UI", Arial, sans-serif';
  if (!letterSpacingEm || text.length <= 1) {
    ctx.textAlign = align;
    ctx.fillText(text, 0, 0);
  } else {
    const px = sizeU * 1000;
    const gap = letterSpacingEm * px;
    let totalW = 0;
    const ws = [];
    for (let i = 0; i < text.length; i++) {
      const w = ctx.measureText(text[i]).width;
      ws.push(w);
      totalW += w;
      if (i < text.length - 1) totalW += gap;
    }
    let cur = align === 'center' ? -totalW * 0.5 : (align === 'right' ? -totalW : 0);
    ctx.textAlign = 'left';
    for (let i = 0; i < text.length; i++) {
      ctx.fillText(text[i], cur, 0);
      cur += ws[i] + gap;
    }
  }
  ctx.restore();
}

function k19DrawLedDot(ctx, x, y, r, color, lit) {
  ctx.beginPath();
  ctx.arc(x, y, r * 1.38, 0, K19_TAU);
  ctx.fillStyle = K19_PALETTE.ledBezel;
  ctx.fill();

  ctx.beginPath();
  ctx.arc(x, y, r, 0, K19_TAU);
  ctx.fillStyle = lit ? color : K19_PALETTE.ledOff;
  ctx.fill();

  if (lit) {
    ctx.beginPath();
    ctx.arc(x - r * 0.22, y - r * 0.22, r * 0.26, 0, K19_TAU);
    ctx.fillStyle = '#FFF6D6';
    ctx.fill();
  }
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const safeLoopT = loopT < 0 ? loopT + duration : loopT;
  const st = k19EvaluateBoardState(safeLoopT);
  const U = Math.min(height, width / (16 / 9));

  ctx.save();
  ctx.shadowBlur = 0;

  /* 1. Crisp Matte Obsidian Background (Zero Background Glow) */
  const bg = ctx.createLinearGradient(0, 0, 0, height);
  bg.addColorStop(0.0, K19_PALETTE.bgTop);
  bg.addColorStop(0.55, K19_PALETTE.bgMid);
  bg.addColorStop(1.0, K19_PALETTE.bgBot);
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, width, height);

  ctx.translate(width * 0.5, height * 0.5);
  ctx.scale(U, U);

  /* 2. Architectural Split-Flap Board Chassis */
  const bw = 1.50;
  const bh = 0.80;
  k19FillRoundedRect(ctx, -bw * 0.5, -bh * 0.5, bw, bh, 0.022);
  ctx.fillStyle = K19_PALETTE.chassisBg;
  ctx.fill();
  ctx.strokeStyle = K19_PALETTE.chassisBorder;
  ctx.lineWidth = 0.0024;
  ctx.stroke();

  k19FillRoundedRect(ctx, -bw * 0.478, -bh * 0.456, bw * 0.956, bh * 0.912, 0.014);
  ctx.fillStyle = K19_PALETTE.chassisInset;
  ctx.fill();

  /* Four Precision Corner Rivets */
  const rivetPos = [[-0.725, -0.375], [0.725, -0.375], [-0.725, 0.375], [0.725, 0.375]];
  for (let i = 0; i < 4; i++) {
    ctx.beginPath();
    ctx.arc(rivetPos[i][0], rivetPos[i][1], 0.0055, 0, K19_TAU);
    ctx.fillStyle = K19_PALETTE.chassisBorder;
    ctx.fill();
  }

  /* Crisp Header Airplane Icon + Editorial Labels */
  ctx.save();
  ctx.translate(-0.678, -0.316);
  ctx.fillStyle = K19_PALETTE.amber;
  ctx.beginPath();
  ctx.moveTo(-0.014, 0.000);
  ctx.lineTo(0.014, 0.000);
  ctx.lineTo(0.006, -0.005);
  ctx.lineTo(-0.002, -0.005);
  ctx.lineTo(-0.008, -0.013);
  ctx.lineTo(-0.012, -0.013);
  ctx.lineTo(-0.008, -0.002);
  ctx.closePath();
  ctx.fill();
  ctx.restore();

  k19DrawText(ctx, 'DEPARTURES // TERMINAL 2027', -0.650, -0.316, 0.0165, '700', 'left', K19_PALETTE.amberBright, 0.14);
  const phaseTitles = [
    'BOARD INITIALIZING',
    'DESTINATION LOCKED',
    'STATUS // ON TIME',
    'CYCLE STANDBY RESET'
  ];
  k19DrawText(ctx, phaseTitles[currentScene], 0.655, -0.316, 0.014, '600', 'right', K19_PALETTE.slateText, 0.14);
  const topLedLit = (Math.floor((safeLoopT + 0.25) * 2) % 2) === 0 || currentScene === 2;
  k19DrawLedDot(ctx, 0.680, -0.316, 0.0065, K19_PALETTE.amber, topLedLit);

  ctx.strokeStyle = K19_PALETTE.bayBorder;
  ctx.lineWidth = 0.0018;
  ctx.beginPath();
  ctx.moveTo(-0.690, -0.276);
  ctx.lineTo(0.690, -0.276);
  ctx.moveTo(-0.690, 0.268);
  ctx.lineTo(0.690, 0.268);
  ctx.stroke();

  /* 3. Row Bays, Micro Labels & Split-Flap Tiles */
  for (let r = 0; r < K19_ROWS_SPEC.length; r++) {
    const spec = K19_ROWS_SPEC[r];
    k19DrawText(ctx, spec.title, -0.685, spec.headerY, 0.012, '600', 'left', K19_PALETTE.amberLabel, 0.14);
    k19DrawText(ctx, spec.tagRight, 0.685, spec.headerY, 0.0115, '600', 'right', K19_PALETTE.slateText, 0.14);

    const bayPadY = spec.tileH * 0.56;
    ctx.fillStyle = K19_PALETTE.chassisBay;
    ctx.fillRect(-0.690, spec.y - bayPadY, 1.380, bayPadY * 2);
  }

  for (let i = 0; i < st.cells.length; i++) {
    const item = st.cells[i];
    k19DrawSplitFlapCard(ctx, item.cell, item);
  }

  /* 4. Bottom 14-Column Synchronized Amber LED Matrix Bar + Separate Telemetry Label Strip */
  const row2Start = K19_ROWS_SPEC[0].target.length + K19_ROWS_SPEC[1].target.length;
  for (let c = 0; c < 14; c++) {
    const row1Item = st.cells[K19_ROWS_SPEC[0].target.length + c];
    const row2Item = st.cells[row2Start + c];
    const cx = row2Item.cell.cx;
    const isBlinkWindow = st.blinkEnv > 0.05;
    const phaseHigh = st.blinkPulse > 0.46;
    const ledLit = isBlinkWindow
      ? (phaseHigh ? (c % 2 === 0 || c >= 7) : (c % 2 === 1 && c < 7))
      : (row1Item.locked || row2Item.locked);
    k19DrawLedDot(ctx, cx, 0.296, 0.0058, phaseHigh ? K19_PALETTE.amberBright : K19_PALETTE.amber, ledLit);
  }

  k19DrawText(ctx, 'GATE TELEMETRY // 14-CH MATRIX', -0.685, 0.340, 0.0115, '600', 'left', K19_PALETTE.slateText, 0.14);
  k19DrawText(ctx, 'SOLARI MECHANICAL SPLIT-FLAP • EDITION XIX', 0.685, 0.340, 0.0115, '600', 'right', K19_PALETTE.amberLabel, 0.12);

  ctx.restore();
}
